// ==========================================
// CART & ORDER PERSISTENCE — Firebase Realtime Database + localStorage fallback
// ==========================================

// ── Helper: sanitize phone/id เพื่อใช้เป็น Firebase key (ห้ามมี . # $ [ ])
function toFirebaseKey(str) {
    return (str || "guest").replace(/[.#$\[\]]/g, "_");
}

// ── ตรวจสอบว่า Firebase พร้อมใช้งานหรือไม่
function isFirebaseReady() {
    return typeof db !== "undefined" && db !== null;
}

// ── CART: โหลดจาก localStorage (initial load; Firebase listener จะ update ทีหลัง)
function loadSavedCart() {
    try {
        const saved = localStorage.getItem("talathub_cart");
        if (saved) {
            const parsed = JSON.parse(saved);
            if (Array.isArray(parsed)) return parsed;
        }
    } catch (e) { }
    return [];
}

// ── CART: บันทึกทั้ง localStorage (instant) และ Firebase (cross-device)
function saveCartToStorage(cart) {
    // 1. localStorage — ทำให้ UI ไม่กระตุก (ทันที)
    try {
        localStorage.setItem("talathub_cart", JSON.stringify(cart || []));
    } catch (e) { }

    // 2. Firebase — sync ข้ามอุปกรณ์
    if (isFirebaseReady() && state.customer && state.customer.isLoggedIn) {
        const customerId = toFirebaseKey(state.customer.identifier);
        db.ref(`carts/${customerId}`).set({
            items: cart || [],
            updatedAt: Date.now(),
            customerName: state.customer.identifier
        }).catch(e => console.warn("Firebase cart save failed:", e));
    }
}

// ── ORDER: โหลดจาก localStorage (initial load)
function loadSavedActiveOrder() {
    const mockOrderIds = ["#TH-6114", "#TH-8101", "#TH-8102", "#TH-8103", "#TH-5324", "#TH-9568", "#TH-4692", "TH-6114", "TH-8101", "TH-8102", "TH-8103", "TH-5324", "TH-9568", "TH-4692"];
    
    // 1. ลองโหลดจาก talathub_active_order หรือ hsong_active_order
    try {
        const keys = ["talathub_active_order", "hsong_active_order"];
        for (const key of keys) {
            const saved = localStorage.getItem(key);
            if (saved) {
                const parsed = JSON.parse(saved);
                if (parsed && parsed.orderId && !mockOrderIds.includes(parsed.orderId) && !parsed.orderId.startsWith("#TH-810")) {
                    if (parsed.status !== "delivered") {
                        return parsed;
                    }
                }
            }
        }
    } catch (e) { }

    // 2. ลองโหลดจากรายการงานด่วนแผงค้า (merchant express orders)
    try {
        const expSaved = localStorage.getItem("hsong_merchant_express_orders");
        if (expSaved) {
            const expList = JSON.parse(expSaved);
            if (Array.isArray(expList) && expList.length > 0) {
                const activeExp = expList.find(o => o && o.orderId && o.status !== "delivered");
                if (activeExp) return activeExp;
            }
        }
    } catch (e) { }

    return null;
}

function loadSavedMerchantExpressOrders() {
    try {
        const expSaved = localStorage.getItem("hsong_merchant_express_orders");
        if (expSaved) {
            const expList = JSON.parse(expSaved);
            if (Array.isArray(expList)) return expList;
        }
    } catch (e) { }
    return [];
}

// ✅ ล้างข้อมูลทดสอบทั้งหมด สำหรับเริ่มต้นใช้งานจริง
function clearAllTestData() {
    localStorage.removeItem("talathub_active_order");
    localStorage.removeItem("talathub_cart");
    localStorage.removeItem("talathub_delivery_location");
    localStorage.removeItem("talathub_order_history");
    localStorage.removeItem("talathub_community_riders");
    localStorage.removeItem("talathub_logged_in_rider");
    localStorage.removeItem("talathub_custom_market_stalls");
    localStorage.removeItem("talathub_pending_stalls");
    localStorage.removeItem("talathub_wallet_transactions");
    localStorage.removeItem("talathub_rating_reviews");
    localStorage.removeItem("talathub_mock_orders");
    localStorage.removeItem("hsong_merchant_express_orders");
    localStorage.removeItem("hsong_active_order");

    // ล้าง Firebase orders ทั้งหมด
    if (isFirebaseReady()) {
        db.ref("orders").remove().catch(e => console.warn("Firebase clear failed:", e));
        if (state.customer && state.customer.isLoggedIn) {
            const cid = toFirebaseKey(state.customer.identifier);
            db.ref(`carts/${cid}`).remove().catch(() => {});
        }
    }

    // ล้าง state
    state.activeOrder = null;
    state.cart = [];
    state.deliveryLocation = null;
    state.activeRider = null;
    state.merchantExpressOrders = [];

    // อัปเดต UI
    const hubBadge = document.getElementById("hub-badge-count");
    if (hubBadge) { hubBadge.classList.add("hidden"); hubBadge.textContent = ""; }
    updateDeliveryLocationUI();
    updateCartUI();
    renderCatalog();
    if (typeof renderHubPickingList === "function") renderHubPickingList();
    if (typeof renderHubSettlement === "function") renderHubSettlement();
    if (typeof renderMerchantActiveDeliveries === "function") renderMerchantActiveDeliveries();
    renderTrackingScreen();
    if (typeof renderRiderScreen === "function") renderRiderScreen();
    renderAuthHeaderButtons();

    showToast("🗑️ ล้างข้อมูลทดสอบทั้งหมดเรียบร้อยแล้ว! ระบบสะอาด 100%");
}

// ── ORDER ARCHIVE: บันทึกออเดอร์ลง talathub_order_history สำหรับคำนวณรายงานประจำวัน
function archiveOrderToHistory(order) {
    if (!order || !order.orderId) return;
    const mockOrderIds = ["#TH-6114", "#TH-8101", "#TH-8102", "#TH-8103", "#TH-5324", "#TH-9568", "#TH-4692", "TH-6114", "TH-8101", "TH-8102", "TH-8103", "TH-5324", "TH-9568", "TH-4692"];
    if (mockOrderIds.includes(order.orderId) || order.orderId.startsWith("#TH-810")) return;
    try {
        let hist = JSON.parse(localStorage.getItem("talathub_order_history") || "[]");
        hist = hist.filter(o => o && o.orderId && !mockOrderIds.includes(o.orderId) && !o.orderId.startsWith("#TH-810"));
        const idx = hist.findIndex(o => o.orderId === order.orderId);
        const orderToSave = { ...order, savedAt: order.savedAt || Date.now() };
        if (idx >= 0) {
            hist[idx] = { ...hist[idx], ...orderToSave };
        } else {
            hist.push(orderToSave);
        }
        if (hist.length > 300) hist = hist.slice(-300);
        localStorage.setItem("talathub_order_history", JSON.stringify(hist));
    } catch (e) {
        console.warn("archiveOrderToHistory error:", e);
    }
}

// ── ORDER: บันทึกทั้ง localStorage และ Firebase
function saveActiveOrderToStorage(order) {
    // 1. localStorage
    try {
        if (order) {
            if (!order.savedAt) order.savedAt = Date.now();
            localStorage.setItem("talathub_active_order", JSON.stringify(order));
            if (order.orderType === "MERCHANT_EXPRESS" || (order.orderId && order.orderId.startsWith("EXP-"))) {
                localStorage.setItem("hsong_active_order", JSON.stringify(order));
                let expOrders = [];
                try { expOrders = JSON.parse(localStorage.getItem("hsong_merchant_express_orders") || "[]"); } catch(e) {}
                const idx = expOrders.findIndex(o => o.orderId === order.orderId);
                if (idx >= 0) expOrders[idx] = order;
                else expOrders.unshift(order);
                localStorage.setItem("hsong_merchant_express_orders", JSON.stringify(expOrders.slice(0, 20)));
            }
            archiveOrderToHistory(order);
        } else {
            localStorage.removeItem("talathub_active_order");
        }
    } catch (e) { }

    // 2. Firebase — push order เพื่อให้ Hub/PC เห็นทันที
    if (isFirebaseReady() && order) {
        const orderKey = toFirebaseKey(order.orderId);
        db.ref(`orders/${orderKey}`).set({
            ...order,
            savedAt: order.savedAt || Date.now(),
            status: order.status || "picking"
        }).catch(e => console.warn("Firebase order save failed:", e));
    } else if (isFirebaseReady() && !order) {
        // ไม่ลบ เพื่อให้ประวัติยังอยู่
    }
}

// ── ORDER STATUS: อัปเดต status ใน Firebase (Hub อัปเดตเพื่อให้มือถือเห็น)
function updateOrderStatusInFirebase(orderId, newStatus) {
    if (!isFirebaseReady() || !orderId) return;
    const orderKey = toFirebaseKey(orderId);
    db.ref(`orders/${orderKey}/status`).set(newStatus)
      .catch(e => console.warn("Firebase status update failed:", e));
}

// ✅ ปุ่ม "ซิงค์สด" — ดึงออเดอร์ล่าสุดจาก Firebase Cloud หรือ LocalStorage มาอัปเดตหน้าจอ Hub ทันที
async function syncLatestOrderFromCloud() {
    try {
        let syncedOrder = null;

        // 1. ตรวจสอบและดึงข้อมูลจาก Firebase Realtime Database (Cloud)
        if (isFirebaseReady()) {
            const snapshot = await db.ref("orders").limitToLast(10).once("value");
            const data = snapshot.val();
            if (data) {
                // หา order ล่าสุดที่ยังไม่ delivered และมี savedAt
                const ordersList = Object.values(data).filter(o => o && o.orderId && o.status !== "delivered");
                if (ordersList.length > 0) {
                    ordersList.sort((a, b) => (b.savedAt || 0) - (a.savedAt || 0));
                    syncedOrder = ordersList[0];
                }
            }
        }

        // 2. ถ้าคลาวด์ไม่มี หรือออฟไลน์ ให้ fallback มาดูที่ localStorage ของเครื่อง
        if (!syncedOrder) {
            syncedOrder = loadSavedActiveOrder();
        }

        // โหลดข้อมูล Express Orders ของแผงค้าด้วย
        try {
            const expRaw = localStorage.getItem("hsong_merchant_express_orders");
            if (expRaw) {
                state.merchantExpressOrders = JSON.parse(expRaw);
            }
        } catch(e) {}

        // 3. นำข้อมูลมาอัปเดตลง State และอัปเดตหน้าจอ Hub
        if (syncedOrder && syncedOrder.orderId) {
            state.activeOrder = syncedOrder;
            try { localStorage.setItem("talathub_active_order", JSON.stringify(syncedOrder)); } catch (e) {}
        }

        // อัปเดตหน้าจอ Hub ทันที
        if (typeof renderHubPickingList === "function") renderHubPickingList();
        if (typeof renderHubSettlement === "function") renderHubSettlement();
        if (typeof renderMerchantActiveDeliveries === "function") renderMerchantActiveDeliveries();
            
        const hubBadge = document.getElementById("hub-badge-count");
        if (hubBadge) {
            hubBadge.classList.remove("hidden");
            hubBadge.textContent = "SYNCED";
        }
            
        if (syncedOrder && syncedOrder.orderId) {
            showToast(`✅ ซิงค์สำเร็จ! ดึงออเดอร์ ${syncedOrder.orderId} เข้าสู่ใบจัดของแล้ว`);
        } else if (state.merchantExpressOrders && state.merchantExpressOrders.length > 0) {
            showToast(`✅ ซิงค์สำเร็จ! ตรวจพบงานด่วนแผงค้า ${state.merchantExpressOrders.length} รายการ`);
        } else {
            showToast("ℹ️ ระบบคลาวด์ปกติ: ยังไม่มีออเดอร์ใหม่ที่ค้างจัด");
        }
    } catch (err) {
        console.error("syncLatestOrderFromCloud error:", err);
        const localOrder = loadSavedActiveOrder();
        if (localOrder) {
            state.activeOrder = localOrder;
            if (typeof renderHubPickingList === "function") renderHubPickingList();
            if (typeof renderHubSettlement === "function") renderHubSettlement();
            showToast(`⚠️ ซิงค์ออฟไลน์: โหลดออเดอร์ ${localOrder.orderId} จากเครื่องแล้ว`);
        } else {
            showToast("⚠️ ไม่พบออเดอร์ค้างในระบบ");
        }
    }
}



function isCustomOrApprovedStall(s) {
    if (!s || !s.stallId) return false;
    const id = s.stallId;
    return s.isModified === true || id.startsWith("stall_new_") || id.startsWith("APP-SHOP-") || id.startsWith("stall_custom_") || id.startsWith("stall_seed_") || !!s.accessCode;
}

function loadSavedMarketData() {
    try {
        const saved = localStorage.getItem("talathub_custom_market_stalls");
        if (saved) {
            const parsed = JSON.parse(saved);
            if (Array.isArray(parsed) && parsed.length > 0) {
                const validCustom = parsed.filter(isCustomOrApprovedStall);
                localStorage.setItem("talathub_custom_market_stalls", JSON.stringify(validCustom));
                return validCustom;
            }
        }
    } catch (e) { }
    return [];
}

function saveMarketDataToStorage() {
    try {
        const customOnly = MARKET_DATA.filter(isCustomOrApprovedStall);
        try {
            localStorage.setItem("talathub_custom_market_stalls", JSON.stringify(customOnly));
        } catch (storageErr) {
            console.warn("localStorage quota exceeded for custom_market_stalls:", storageErr);
        }
        if (isFirebaseReady() && db) {
            db.ref("custom_market_stalls").set(customOnly).catch(err => {
                console.warn("Firebase save custom_market_stalls failed:", err);
            });
        }
        try {
            fetch("https://hsong-1f342-default-rtdb.asia-southeast1.firebasedatabase.app/custom_market_stalls.json", {
                method: "PUT",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(customOnly)
            }).catch(() => {});
        } catch (e) {}
    } catch (e) { }
}

async function saveMarketDataToStorageAsync() {
    try {
        const customOnly = MARKET_DATA.filter(isCustomOrApprovedStall);
        try {
            localStorage.setItem("talathub_custom_market_stalls", JSON.stringify(customOnly));
        } catch (storageErr) {
            console.warn("localStorage quota exceeded for custom_market_stalls:", storageErr);
        }
        const promises = [];
        if (isFirebaseReady() && db) {
            promises.push(
                db.ref("custom_market_stalls").set(customOnly).catch(err => {
                    console.warn("Firebase save custom_market_stalls failed:", err);
                })
            );
        }
        try {
            promises.push(
                fetch("https://hsong-1f342-default-rtdb.asia-southeast1.firebasedatabase.app/custom_market_stalls.json", {
                    method: "PUT",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify(customOnly)
                }).catch(e => console.warn("REST PUT custom_market_stalls failed:", e))
            );
        } catch (e) {}
        await Promise.allSettled(promises);
    } catch (e) { }
}
window.saveMarketDataToStorageAsync = saveMarketDataToStorageAsync;

let _isCustomStallsSyncInitialized = false;
function initCustomStallsRealtimeSync() {
    if (!isFirebaseReady() || _isCustomStallsSyncInitialized) return;
    _isCustomStallsSyncInitialized = true;

    db.ref("custom_market_stalls").on("value", snapshot => {
        try {
            const data = snapshot.val();
            let rawList = [];
            if (Array.isArray(data)) {
                rawList = data.filter(Boolean);
            } else if (data && typeof data === "object") {
                rawList = Object.values(data).filter(Boolean);
            }

            if (rawList.length > 0) {
                localStorage.setItem("talathub_custom_market_stalls", JSON.stringify(rawList));
                rawList.forEach(savedStall => {
                    const existingIdx = MARKET_DATA.findIndex(s => s.stallId === savedStall.stallId);
                    if (existingIdx >= 0) {
                        MARKET_DATA[existingIdx] = { ...MARKET_DATA[existingIdx], ...savedStall };
                    } else {
                        MARKET_DATA.push(savedStall);
                    }

                    if (typeof ALL_100_STALLS !== "undefined" && Array.isArray(ALL_100_STALLS)) {
                        const allIdx = ALL_100_STALLS.findIndex(s => s.stallId === savedStall.stallId);
                        if (allIdx >= 0) {
                            ALL_100_STALLS[allIdx] = { ...ALL_100_STALLS[allIdx], ...savedStall };
                        } else {
                            ALL_100_STALLS.push(savedStall);
                        }
                    }
                });

                if (typeof renderCatalog === "function") renderCatalog();
                if (typeof renderDirectoryList === "function") renderDirectoryList();
                if (typeof renderFavoriteStallsBar === "function") renderFavoriteStallsBar();
                if (typeof updateStallRotationUI === "function") updateStallRotationUI();
                if (state.currentRole === "merchant" && typeof renderMerchantView === "function") {
                    renderMerchantView();
                }
            }
        } catch (err) {
            console.warn("Error syncing custom_market_stalls:", err);
        }
    });
}
window.initCustomStallsRealtimeSync = initCustomStallsRealtimeSync;

// Restore saved custom stalls if available (merge with base categories and all 100 stalls)
const _savedStalls = loadSavedMarketData();
if (_savedStalls && Array.isArray(_savedStalls) && _savedStalls.length > 0) {
    _savedStalls.forEach(savedStall => {
        const existingIdx = MARKET_DATA.findIndex(s => s.stallId === savedStall.stallId);
        if (existingIdx >= 0) {
            MARKET_DATA[existingIdx] = savedStall;
        } else {
            MARKET_DATA.push(savedStall);
        }

        if (typeof ALL_100_STALLS !== "undefined" && Array.isArray(ALL_100_STALLS)) {
            const allIdx = ALL_100_STALLS.findIndex(s => s.stallId === savedStall.stallId);
            if (allIdx >= 0) {
                ALL_100_STALLS[allIdx] = savedStall;
            } else {
                ALL_100_STALLS.push(savedStall);
            }
        }
    });
}

