// ==========================================
// RANDOMIZED STALL DISPLAY SYSTEM (ระบบสุ่มหมุนเวียนร้านค้าตามหมวดหมู่)
// ==========================================

function selectRandomStallBatch() {
    let pool = MARKET_DATA;

    // รวบรวมร้านค้าที่ได้รับการอนุมัติใหม่/ร้านค้าที่ผู้ใช้ลงทะเบียนจริงขึ้นแสดงเป็นลำดับแรกเสมอ
    const customApproved = pool.filter(s => s && (
        (s.stallId && (s.stallId.startsWith("APP-") || s.stallId.startsWith("stall_new_"))) ||
        s.isModified ||
        s.accessCode
    ));

    // ถ้ามีการเลือกหมวดหมู่เฉพาะ (ไม่ใช่ 'all') ให้สุ่มจากร้านในหมวดหมู่นั้น
    if (state.currentCategoryFilter && state.currentCategoryFilter !== "all") {
        const catPool = pool.filter(s => s.category === state.currentCategoryFilter);
        if (catPool.length > 0) {
            const shuffled = [...catPool].sort(() => 0.5 - Math.random());
            state.stallRotation.displayedStallIds = shuffled.map(s => s.stallId);
            return;
        }
    }

    const selectedStalls = [...customApproved];
    const maxToPick = Math.max(3, selectedStalls.length);

    // สุ่มเลือก 2 ถึง 3 ร้านค้าจากหมวดหมู่ที่แตกต่างกันเพื่อกระจายความหลากหลาย
    const categories = ["chicken", "pork", "veggie", "curry", "seafood"];
    const shuffledCats = [...categories].sort(() => 0.5 - Math.random());

    for (const cat of shuffledCats) {
        if (selectedStalls.length >= maxToPick) break;
        const stallsInCat = pool.filter(s => s.category === cat && !selectedStalls.some(sel => sel.stallId === s.stallId));
        if (stallsInCat.length > 0) {
            const randomStall = stallsInCat[Math.floor(Math.random() * stallsInCat.length)];
            selectedStalls.push(randomStall);
        }
    }

    if (selectedStalls.length < maxToPick) {
        const remaining = pool.filter(s => !selectedStalls.some(sel => sel.stallId === s.stallId));
        const shuffledRemaining = [...remaining].sort(() => 0.5 - Math.random());
        selectedStalls.push(...shuffledRemaining.slice(0, maxToPick - selectedStalls.length));
    }

    state.stallRotation.displayedStallIds = selectedStalls.map(s => s.stallId);
}

function startStallRotationTimer() {
    if (state.stallRotation.timer) {
        clearInterval(state.stallRotation.timer);
    }
    state.stallRotation.timer = setInterval(() => {
        const eligibleStalls = MARKET_DATA.filter(s => s.products && s.products.length > 0);
        // ถ้ามีร้านค้าแค่ 1 ร้าน (ยังไม่มีร้านอื่นมาลงทะเบียน) หรือ พักไว้ หรือ ค้นหา ให้หยุดนับ
        if (eligibleStalls.length <= 1 || state.stallRotation.isPaused || state.searchQuery || state.currentSingleStall || state.currentScreen !== "market" || isMerchantModalOpen()) {
            updateStallRotationUI();
            return;
        }

        state.stallRotation.remainingSeconds--;
        if (state.stallRotation.remainingSeconds <= 0) {
            state.stallRotation.remainingSeconds = state.stallRotation.intervalSeconds;
            selectRandomStallBatch();
            renderCatalog();
        } else {
            updateStallRotationUI();
        }
    }, 1000);
}

function updateStallRotationUI() {
    const timerText = document.getElementById("rotation-countdown-text");
    const toggleIcon = document.getElementById("toggle-rotation-icon");
    const toggleBtn = document.getElementById("toggle-rotation-btn");
    const rotBar = document.getElementById("random-rotation-bar");

    if (!rotBar) return;

    // ซ่อนแถบถ้ามีร้านค้าไม่เกิน 1 ร้าน (ยังไม่มีร้านลงทะเบียนเพิ่ม) หรือกำลังดูเฉพาะแผง หรือ กำลังค้นหา
    const eligibleStalls = MARKET_DATA.filter(s => s.products && s.products.length > 0);
    if (eligibleStalls.length <= 1 || state.currentSingleStall || (state.searchQuery && state.searchQuery.trim() !== "")) {
        rotBar.classList.add("hidden");
        return;
    } else {
        rotBar.classList.remove("hidden");
    }

    if (timerText) {
        if (state.stallRotation.isPaused) {
            timerText.textContent = "⏸️ พักการสุ่มหมุนเวียนชั่วคราว";
        } else if (state.currentCategoryFilter !== "all") {
            timerText.textContent = `⏳ หมุนเวียนในหมวดใน ${state.stallRotation.remainingSeconds} วิ`;
        } else {
            timerText.textContent = `⏳ หมุนเวียนรอบถัดไปใน ${state.stallRotation.remainingSeconds} วิ`;
        }
    }

    if (toggleIcon) {
        toggleIcon.textContent = state.stallRotation.isPaused ? "play_arrow" : "pause";
    }
    if (toggleBtn) {
        toggleBtn.title = state.stallRotation.isPaused ? "เริ่มหมุนเวียนต่อ" : "พักการหมุนเวียนชั่วคราว";
    }
}

function triggerManualStallShuffle() {
    state.stallRotation.remainingSeconds = state.stallRotation.intervalSeconds;
    selectRandomStallBatch();
    renderCatalog();
    updateStallRotationUI();
    showToast("🎲 สุ่มแสดงร้านค้าชุดใหม่ตามหมวดหมู่เรียบร้อยแล้ว!");
}

function toggleStallRotationPause() {
    state.stallRotation.isPaused = !state.stallRotation.isPaused;
    updateStallRotationUI();
    showToast(state.stallRotation.isPaused ? "⏸️ พักการสุ่มหมุนเวียนชั่วคราว" : "▶️ เปิดการสุ่มหมุนเวียนต่อ (Auto 30s)");
}

function initStallRotation() {
    if (!state.stallRotation.displayedStallIds || state.stallRotation.displayedStallIds.length === 0) {
        selectRandomStallBatch();
    }
    startStallRotationTimer();
    updateStallRotationUI();
}

function isMerchantModalOpen() {
    const modal = document.getElementById("merchant-portal-modal");
    return modal && !modal.classList.contains("hidden");
}

// ==========================================
// CATALOG FILTERING & RENDERING (SUPER-GROUPS)
// ==========================================
function renderCatalog() {
    const container = document.getElementById("products-catalog-container");
    const singleStallBanner = document.getElementById("single-stall-banner");
    if (!container) return;

    let filteredStalls = MARKET_DATA;
    let isSearchMode = state.searchQuery && state.searchQuery.trim() !== "";
    let isSuggestedMode = false;
    let searchQuery = isSearchMode ? state.searchQuery.trim().toLowerCase() : "";

    // 1. Check if filtered by single stall
    if (state.currentSingleStall) {
        filteredStalls = MARKET_DATA.filter(s => s.stallId === state.currentSingleStall);
        const stallObj = ALL_100_STALLS.find(s => s.stallId === state.currentSingleStall) || MARKET_DATA.find(s => s.stallId === state.currentSingleStall);
        if (singleStallBanner) {
            singleStallBanner.classList.remove("hidden");
            document.getElementById("single-stall-banner-text").textContent = `กำลังดูเฉพาะ: ${stallObj ? stallObj.stallName : ''}`;
        }
    } else if (isSearchMode) {
        if (singleStallBanner) singleStallBanner.classList.add("hidden");
    } else {
        if (singleStallBanner) singleStallBanner.classList.add("hidden");

        // ระบบสุ่มแสดงข้อมูลร้านค้าตามหมวดหมู่
        if (!state.stallRotation.displayedStallIds || state.stallRotation.displayedStallIds.length === 0) {
            selectRandomStallBatch();
        }

        // หากเป็นร้านค้าที่ล็อกอินอยู่ ให้ดึงขึ้นมาแสดงด้านหน้าเสมอ
        if (state.activeMerchant && state.activeMerchant.stallId) {
            const mId = state.activeMerchant.stallId;
            if (MARKET_DATA.some(s => s.stallId === mId)) {
                state.stallRotation.displayedStallIds = [
                    mId,
                    ...state.stallRotation.displayedStallIds.filter(id => id !== mId)
                ];
            }
        }

        let randomized = state.stallRotation.displayedStallIds
            .map(id => MARKET_DATA.find(s => s.stallId === id))
            .filter(Boolean);

        // ถ้ามีการเลือกหมวดหมู่เฉพาะ ให้กรองตามหมวดหมู่นั้น
        if (state.currentCategoryFilter !== "all") {
            randomized = randomized.filter(s => s.category === state.currentCategoryFilter);
            if (randomized.length === 0) {
                selectRandomStallBatch();
                randomized = state.stallRotation.displayedStallIds
                    .map(id => MARKET_DATA.find(s => s.stallId === id))
                    .filter(Boolean);
            }
        }

        filteredStalls = randomized.length > 0 ? randomized : MARKET_DATA;

        // นำร้านของร้านค้าที่ล็อกอินอยู่มาแสดงอันดับแรกในหน้าโฮมเพจ (เมื่อดูทั้งหมด)
        if (state.activeMerchant && state.activeMerchant.stallId && state.currentCategoryFilter === "all") {
            const myStall = MARKET_DATA.find(s => s.stallId === state.activeMerchant.stallId);
            if (myStall) {
                filteredStalls = [myStall, ...filteredStalls.filter(s => s.stallId !== myStall.stallId)];
            }
        }
    }

    // 2. SEARCH ENGINE: Match across up to 5 stalls + Fuzzy Suggestions
    if (isSearchMode) {
        // Step A: Direct Matches across all stalls (checking both 6 featured items and extended catalog)
        let directMatchedStalls = [];

        MARKET_DATA.forEach(stall => {
            const sProducts = (stall && Array.isArray(stall.products)) ? stall.products : [];
            // Check in stall products
            let matchedItems = sProducts.filter(p =>
                p.name.toLowerCase().includes(searchQuery) ||
                p.desc.toLowerCase().includes(searchQuery) ||
                (p.category && p.category.toLowerCase().includes(searchQuery))
            );

            // Also check in stall extended catalog database for more items (e.g. ซี่โครงหมู, สันคอ)
            const extendedCatalog = getStallCatalogData(stall.stallId);
            if (extendedCatalog) {
                extendedCatalog.forEach(group => {
                    group.items.forEach(extItem => {
                        if (extItem.name.toLowerCase().includes(searchQuery) || extItem.spec.toLowerCase().includes(searchQuery)) {
                            // If not already in matched items, add it
                            if (!matchedItems.some(m => m.id === extItem.id)) {
                                matchedItems.push({
                                    id: extItem.id,
                                    name: extItem.name,
                                    desc: extItem.spec,
                                    price: extItem.price,
                                    unit: extItem.unit,
                                    image: stall.stallImage,
                                    badge: "✨ ตรงคำค้น"
                                });
                            }
                        }
                    });
                });
            }

            if (matchedItems.length > 0 || stall.stallName.toLowerCase().includes(searchQuery) || stall.stallTag.toLowerCase().includes(searchQuery)) {
                directMatchedStalls.push({
                    ...stall,
                    products: matchedItems.length > 0 ? matchedItems : sProducts
                });
            }
        });

        if (directMatchedStalls.length > 0) {
            // Limit to up to 5 stalls as requested
            filteredStalls = directMatchedStalls.slice(0, 5);
        } else {
            // Step B: Smart Related / Fuzzy Suggestions when no direct match found
            isSuggestedMode = true;
            let relatedStalls = [];

            // Extract keywords (e.g. หมู, ไก่, ผัก, กุ้ง, ปลา, แกง, ซุป, สด)
            const keywords = ["หมู", "ไก่", "ผัก", "กุ้ง", "ปลา", "แกง", "เนื้อ", "ไข่", "ทะเล", "ซุป", "สด"];
            const matchedKeyword = keywords.find(kw => searchQuery.includes(kw));

            MARKET_DATA.forEach(stall => {
                const sProducts = (stall && Array.isArray(stall.products)) ? stall.products : [];
                let suggestedItems = [];
                if (matchedKeyword) {
                    suggestedItems = sProducts.filter(p =>
                        p.name.includes(matchedKeyword) ||
                        p.desc.includes(matchedKeyword) ||
                        (stall.category && stall.category.includes(matchedKeyword)) ||
                        (stall.stallTag && stall.stallTag.includes(matchedKeyword))
                    );
                } else {
                    // Fallback to top bestsellers across stalls
                    suggestedItems = sProducts.filter(p => p.badge);
                }

                if (suggestedItems.length > 0) {
                    relatedStalls.push({
                        ...stall,
                        products: suggestedItems
                    });
                }
            });

            filteredStalls = relatedStalls.slice(0, 5);
        }
    }

    // 3. Render Empty State
    if (filteredStalls.length === 0) {
        if (!isSearchMode) {
            container.innerHTML = `
                <div class="text-center py-16 px-4 bg-white rounded-3xl border border-slate-200 shadow-xs space-y-3">
                    <div class="w-16 h-16 rounded-2xl bg-emerald-50 text-emerald-600 font-bold flex items-center justify-center text-3xl mx-auto border border-emerald-100">
                        🏪
                    </div>
                    <div class="space-y-1">
                        <h3 class="font-extrabold text-base text-slate-800">ยังไม่มีแผงค้าเปิดให้บริการในขณะนี้</h3>
                        <p class="text-xs text-slate-500 max-w-md mx-auto">ระบบเตรียมพร้อมรองรับข้อมูลจริงจากการลงทะเบียนร้านค้า สามารถลงทะเบียนเปิดร้านค้าใหม่ หรือเข้าไปที่ศูนย์แอดมินเพื่ออนุมัติร้านค้าได้ทันที</p>
                    </div>
                    <div class="flex items-center justify-center gap-2 pt-2">
                        <button onclick="registerNewMerchantStall()" class="px-4 py-2 bg-gradient-to-r from-emerald-600 to-teal-700 hover:from-emerald-700 hover:to-teal-800 text-white font-extrabold rounded-xl text-xs shadow-md flex items-center gap-1.5 active:scale-95 transition-all cursor-pointer">
                            <span class="material-symbols-outlined text-sm font-bold">add_business</span>
                            <span>ลงทะเบียนเปิดร้านค้าใหม่</span>
                        </button>
                        <button onclick="switchRole('admin')" class="px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold rounded-xl text-xs flex items-center gap-1.5 active:scale-95 transition-all cursor-pointer">
                            <span class="material-symbols-outlined text-sm">admin_panel_settings</span>
                            <span>เข้าสู่ศูนย์แอดมิน</span>
                        </button>
                    </div>
                </div>
            `;
            return;
        }

        container.innerHTML = `
            <div class="text-center py-12 text-slate-400 bg-white rounded-2xl border border-slate-200 p-6 shadow-xs">
                <span class="material-symbols-outlined text-4xl mb-1 text-slate-300">manage_search</span>
                <p class="text-xs font-bold text-slate-700">ไม่พบสินค้า "${state.searchQuery}" ในตลาดสด</p>
                <p class="text-[11px] text-slate-400 mt-1">ลองค้นหาด้วยคำง่ายๆ เช่น อกไก่, ซี่โครงหมู, ผักกาดขาว, กุ้งสด</p>
                <div class="flex flex-wrap items-center justify-center gap-1.5 mt-3.5">
                    <button onclick="handleQuickSearch('อกไก่')" class="px-2.5 py-1 bg-emerald-50 text-emerald-800 border border-emerald-200 rounded-lg text-xs font-bold hover:bg-emerald-100">🍗 อกไก่</button>
                    <button onclick="handleQuickSearch('หมู')" class="px-2.5 py-1 bg-pink-50 text-pink-800 border border-pink-200 rounded-lg text-xs font-bold hover:bg-pink-100">🥩 หมูสด</button>
                    <button onclick="handleQuickSearch('ผัก')" class="px-2.5 py-1 bg-green-50 text-green-800 border border-green-200 rounded-lg text-xs font-bold hover:bg-green-100">🥬 ผักสด</button>
                    <button onclick="handleQuickSearch('กุ้ง')" class="px-2.5 py-1 bg-cyan-50 text-cyan-800 border border-cyan-200 rounded-lg text-xs font-bold hover:bg-cyan-100">🦐 กุ้งสด</button>
                </div>
                <button onclick="clearSearchInput()" class="mt-4 px-3.5 py-1.5 bg-emerald-700 hover:bg-emerald-800 text-white rounded-xl text-xs font-bold shadow-xs">ดูสินค้าทั้งหมด</button>
            </div>
        `;
        return;
    }

    let html = "";

    // Search Result Summary Header Banner
    if (isSearchMode) {
        if (!isSuggestedMode) {
            html += `
                <div class="bg-emerald-50 border border-emerald-300 rounded-2xl p-3 flex items-center justify-between text-xs text-emerald-900 shadow-xs mb-1">
                    <div class="flex items-center gap-2">
                        <span class="material-symbols-outlined text-emerald-700 text-lg">check_circle</span>
                        <div>
                            <span class="font-bold">ผลการค้นหา: </span>
                            <span class="font-extrabold text-emerald-800">"${state.searchQuery}"</span>
                            <span class="text-slate-500 text-[11px] block sm:inline"> (พบใน ${filteredStalls.length} ร้านค้า พร้อมกดสั่งซื้อได้ทันที)</span>
                        </div>
                    </div>
                    <button onclick="clearSearchInput()" class="text-emerald-700 hover:text-emerald-900 font-bold text-[11px] flex items-center gap-0.5 shrink-0 bg-white px-2 py-1 rounded-lg border border-emerald-200">
                        <span>ล้างค้นหา</span>
                        <span class="material-symbols-outlined text-xs">close</span>
                    </button>
                </div>
            `;
        } else {
            html += `
                <div class="bg-amber-50 border border-amber-300 rounded-2xl p-3 flex items-center justify-between text-xs text-amber-950 shadow-xs mb-1">
                    <div class="flex items-center gap-2">
                        <span class="material-symbols-outlined text-amber-600 text-lg">lightbulb</span>
                        <div>
                            <span class="font-bold">ไม่พบชื่อตรงตัว "${state.searchQuery}"</span>
                            <span class="text-amber-800 text-[11px] block">เราพบ <strong>สินค้าใกล้เคียงที่เกี่ยวข้อง</strong> จาก ${filteredStalls.length} ร้านค้าให้คุณเลือก:</span>
                        </div>
                    </div>
                    <button onclick="clearSearchInput()" class="text-amber-800 hover:text-amber-950 font-bold text-[11px] flex items-center gap-0.5 shrink-0 bg-white px-2 py-1 rounded-lg border border-amber-200">
                        <span>ดูทั้งหมด</span>
                        <span class="material-symbols-outlined text-xs">close</span>
                    </button>
                </div>
            `;
        }
    }

    filteredStalls.forEach(stall => {
        if (!stall) return;
        if (!stall.products || !Array.isArray(stall.products)) stall.products = [];
        const stallImg = stall.stallImage || 'https://images.unsplash.com/photo-1542838132-92c53300491e?w=700&auto=format&fit=crop&q=80';
        const ownerImg = stall.ownerImage || 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=200&auto=format&fit=crop&q=80';
        const ownerBannerUrl = (typeof getOrBuildOwnerBanner === "function") ? getOrBuildOwnerBanner(stall) : ownerImg;
        const phoneNum = stall.phone || '081-234-5678';
        const ownerNm = stall.ownerName || 'เจ้าของแผงค้า';
        const expText = stall.experience || 'เปิดบริการในตลาดสด';
        const highlightText = stall.highlight || 'สินค้าสดใหม่ คัดเกรดคุณภาพ สะอาด ถูกหลักอนามัย';
        const descriptionText = stall.shopDescription || 'จำหน่ายสินค้าสดคุณภาพดี คัดสรรวันต่อวัน ชั่งน้ำหนักแม่นยำ พร้อมบริการตัดแต่งตามสั่งและจัดส่งตรงถึงบ้านคุณ';
        const isFav = state.favorites && state.favorites.includes(stall.stallId);
        const extraCatalog = getStallCatalogData(stall.stallId);
        const extraItemsCount = extraCatalog.reduce((sum, g) => sum + (g.items ? g.items.length : 0), 0);
        const hasExtraCatalog = extraItemsCount > 0;

        // Collect all stall photos (up to 3 storefront photos)
        const stallPhotosList = (stall.stallImages && Array.isArray(stall.stallImages) && stall.stallImages.length > 0)
            ? stall.stallImages.filter(Boolean)
            : [stall.stallImage, stall.stallImage2, stall.stallImage3].filter(Boolean);
        if (stallPhotosList.length === 0) stallPhotosList.push(stallImg || MERCHANT_PRESET_IMAGES.stall.chicken);
        const ownerSlideIdx = stallPhotosList.length;
        const totalBannerSlides = stallPhotosList.length + 1;

        // Fallback: if stall.products is empty or missing, populate from catalog items so products always show!
        let stallProducts = (stall.products && Array.isArray(stall.products))
            ? stall.products.filter(p => p && p.name && p.name.trim())
            : [];
        if (stallProducts.length === 0 && extraCatalog && Array.isArray(extraCatalog) && extraCatalog.length > 0) {
            extraCatalog.forEach(g => {
                (g.items || []).forEach(it => {
                    if (it && it.name && it.name.trim()) {
                        stallProducts.push({
                            id: it.id || `${stall.stallId}_cat_${stallProducts.length + 1}`,
                            name: it.name.trim(),
                            desc: it.spec || it.subCat || it.mainCat || "",
                            price: it.price || 0,
                            unit: it.unit || "กก.",
                            badge: "สินค้าแนะนำ",
                            image: it.image || stall.stallImage || MERCHANT_PRESET_IMAGES.stall.chicken,
                            mainCat: it.mainCat || g.groupName || "",
                            subCat: it.subCat || ""
                        });
                    }
                });
            });
        }

        html += `
            <div class="bg-white rounded-2xl shadow-card border border-slate-200/80 overflow-hidden space-y-3 pb-3.5 transition-all">
                
                <!-- ======================================================== -->
                <!-- STALL PROFILE CARD: 1 Shop Image + 1 Owner Image         -->
                <!-- + Highlight + Product Description + Direct Phone Call   -->
                <!-- + Interactive Favorite Toggle Button (Persisted)        -->
                <!-- ======================================================== -->
                <div class="bg-gradient-to-b from-slate-50/90 to-white border-b border-slate-200/70">
                    
                    <!-- 🌟 HERO BANNER CAROUSEL (สลับ 1-3 ภาพหน้าร้านค้า & ภาพเจ้าของร้าน รวม ${totalBannerSlides} สไลด์) -->
                    <div id="stall-banner-container-${stall.stallId}" class="relative h-44 sm:h-52 w-full overflow-hidden bg-slate-950 group select-none">
                        <!-- Slides Track -->
                        <div id="stall-carousel-track-${stall.stallId}" class="flex transition-transform duration-500 ease-out h-full w-full">
                            ${stallPhotosList.map((photoUrl, pIdx) => `
                                <!-- Slide ${pIdx + 1}: ภาพแผงค้า/หน้าร้าน ${pIdx + 1} -->
                                <div class="min-w-full h-full relative cursor-pointer bg-slate-950 overflow-hidden flex items-center justify-center" onclick="nextStallBannerSlide('${stall.stallId}', event)">
                                    <img src="${photoUrl}" alt="" class="absolute inset-0 w-full h-full object-cover blur-md scale-110 opacity-30 select-none pointer-events-none">
                                    <img src="${photoUrl}" alt="ภาพร้านค้า ${stall.stallName} (รูปที่ ${pIdx + 1})" class="relative w-full h-full object-cover object-center">
                                    <div class="absolute inset-0 bg-gradient-to-t from-black/30 via-transparent to-transparent pointer-events-none"></div>
                                </div>
                            `).join('')}

                            <!-- Slide ${ownerSlideIdx + 1}: ภาพเจ้าของแผงค้า (Composite Owner Template & Name Badge) -->
                            <div class="min-w-full h-full relative cursor-pointer bg-slate-950 overflow-hidden flex items-center justify-center" onclick="nextStallBannerSlide('${stall.stallId}', event)">
                                <img id="stall-owner-banner-blur-${stall.stallId}" src="${ownerBannerUrl || ownerImg}" alt="" class="absolute inset-0 w-full h-full object-cover blur-md scale-110 opacity-40 select-none pointer-events-none">
                                <img id="stall-owner-banner-img-${stall.stallId}" src="${ownerBannerUrl || ownerImg}" alt="ภาพเจ้าของร้าน ${ownerNm}" class="relative w-full h-full object-contain sm:object-cover object-center">
                                <div class="absolute inset-0 bg-gradient-to-t from-black/20 via-transparent to-transparent pointer-events-none"></div>
                            </div>
                        </div>

                        <!-- 1. ปุ่มเลื่อนภาพไปข้างหน้าถอยหลัง (Prev & Next Chevrons) -->
                        <button type="button" onclick="prevStallBannerSlide('${stall.stallId}', event)" class="absolute left-2 top-1/2 -translate-y-1/2 w-8 h-8 rounded-full bg-black/50 hover:bg-black/80 text-white flex items-center justify-center backdrop-blur-xs transition-all z-20 opacity-80 hover:opacity-100 active:scale-90 shadow-md" title="รูปก่อนหน้า">
                            <span class="material-symbols-outlined text-base">chevron_left</span>
                        </button>
                        <button type="button" onclick="nextStallBannerSlide('${stall.stallId}', event)" class="absolute right-2 top-1/2 -translate-y-1/2 w-8 h-8 rounded-full bg-black/50 hover:bg-black/80 text-white flex items-center justify-center backdrop-blur-xs transition-all z-20 opacity-80 hover:opacity-100 active:scale-90 shadow-md" title="รูปถัดไป">
                            <span class="material-symbols-outlined text-base">chevron_right</span>
                        </button>

                        <!-- Indicator Dots -->
                        <div id="stall-dots-${stall.stallId}" class="absolute bottom-2 left-1/2 -translate-x-1/2 flex items-center gap-1.5 z-20 pointer-events-auto bg-black/40 px-2 py-0.5 rounded-full backdrop-blur-xs">
                            ${Array.from({ length: totalBannerSlides }).map((_, dIdx) => `
                                <button type="button" onclick="goToStallBannerSlide('${stall.stallId}', ${dIdx}, event)" class="stall-banner-dot ${dIdx === 0 ? 'w-4 h-1.5 rounded-full bg-emerald-400' : 'w-1.5 h-1.5 rounded-full bg-white/60 hover:bg-white'} transition-all cursor-pointer" title="สไลด์ที่ ${dIdx + 1}"></button>
                            `).join('')}
                        </div>

                    </div>

                    <!-- Stall Info Header (Name, Favorite Button, Owner Info) -->
                    <div class="px-3.5 pt-3 pb-3">
                        <div class="flex items-center justify-between gap-2 flex-wrap">
                            <!-- Shop Name + ปุ่มบันทึกเป็นร้านโปรดวางต่อกับชื่อร้าน -->
                            <div class="flex items-center gap-2 flex-wrap">
                                <h3 class="font-extrabold text-[16px] text-slate-900 leading-snug flex items-center gap-1.5">
                                    <span>${stall.stallName}</span>
                                    ${stall.isHub ? `<span class="bg-orange-100 text-orange-700 text-[9px] font-bold px-1.5 py-0.2 rounded border border-orange-200">Hub กลาง</span>` : ''}
                                </h3>
                                <!-- ปุ่มบันทึกเป็นร้านโปรด (ยังไม่บันทึก=สีส้ม, บันทึกแล้ว=สีเขียว วางต่อกับชื่อร้าน) -->
                                <button type="button" onclick="toggleFavoriteStall('${stall.stallId}')" class="pointer-events-auto text-[11px] font-black px-3 py-1 rounded-full shadow-xs transition-all flex items-center gap-1 active:scale-95 ${isFav ? 'bg-emerald-600 hover:bg-emerald-700 text-white border border-emerald-500 shadow-emerald-950/20' : 'bg-orange-500 hover:bg-orange-600 text-white border border-orange-400 shadow-xs'}" title="${isFav ? 'อยู่ในร้านโปรดแล้ว (แตะเพื่อยกเลิก)' : 'แตะเพื่อบันทึกเป็นร้านโปรด'}">
                                    <span class="material-symbols-outlined text-[14px] ${isFav ? 'text-yellow-300' : 'text-white'} font-bold">star</span>
                                    <span>${isFav ? 'ร้านโปรดแล้ว ⭐' : 'บันทึกเป็นร้านโปรด'}</span>
                                </button>
                            </div>

                            <!-- เจ้าของแผงค้า (ปุ่มสลับรูป) -->
                            <div class="flex items-center gap-2 text-[11px] text-slate-600">
                                <button type="button" onclick="toggleOwnerBannerSlide('${stall.stallId}', ${ownerSlideIdx}, event)" class="inline-flex items-center gap-1.5 hover:text-emerald-700 transition-colors group/owner text-left bg-slate-100/90 hover:bg-emerald-50 px-2 py-0.5 rounded-lg border border-slate-200/80 cursor-pointer" title="แตะเพื่อสลับดูรูปเจ้าของร้านบนแบนเนอร์">
                                    <span class="relative w-5 h-5 rounded-full ring-1 ring-emerald-500 overflow-hidden shrink-0 inline-block align-middle bg-white">
                                        <img src="${ownerImg}" alt="${ownerNm}" class="w-full h-full object-cover">
                                    </span>
                                    <span class="font-bold text-slate-700 group-hover/owner:text-emerald-700 flex items-center gap-0.5">
                                        <span>${ownerNm}</span>
                                        <span class="material-symbols-outlined text-[13px] text-emerald-600 font-bold" title="ยืนยันตัวตนแล้ว">verified</span>
                                    </span>
                                    <span class="text-[9px] text-emerald-700 bg-emerald-100/70 px-1 py-0.2 rounded font-bold">สลับรูป ↺</span>
                                </button>
                            </div>
                        </div>

                        <!-- Row 2: 3. ข้อความไฮไลท์เพื่อให้ลูกค้ารู้ว่าที่ร้านขายอะไร (Highlight Tagline) -->
                        <div class="mt-3 px-3 py-1.5 rounded-xl bg-amber-50/90 border border-amber-200/90 text-amber-900 flex items-start gap-2 shadow-xs">
                            <span class="material-symbols-outlined text-amber-600 text-base shrink-0 mt-0.5">stars</span>
                            <div class="text-[11px] leading-snug">
                                <span class="font-extrabold text-amber-900">ไฮไลท์สินค้า:</span>
                                <span class="font-medium text-slate-800 ml-1">${highlightText}</span>
                            </div>
                        </div>

                        <!-- Row 3: 4. รายละเอียดของสินค้าที่จำหน่าย (Description ไม่เกิน 150 ตัวอักษร) -->
                        <div class="mt-2 text-[11px] text-slate-600 leading-relaxed bg-slate-50/80 p-2.5 rounded-xl border border-slate-200/70">
                            <div class="flex items-center justify-between font-bold text-slate-700 mb-1 text-[10px]">
                                <span class="flex items-center gap-1 text-emerald-700">
                                    <span class="material-symbols-outlined text-xs">local_mall</span>
                                    รายละเอียดสินค้าที่จำหน่าย
                                </span>
                                <span class="text-slate-400 font-normal text-[9px]">${descriptionText.length} ตัวอักษร</span>
                            </div>
                            <p class="text-slate-600 leading-normal">${descriptionText}</p>
                        </div>

                    </div>
                </div>

                ${stall.isClosed ? `
                    <div class="mx-3.5 my-2 p-2.5 bg-rose-50 border border-rose-200 text-rose-800 rounded-2xl font-bold text-xs flex items-center justify-between shadow-2xs">
                        <span class="flex items-center gap-1.5">
                            <span class="w-2.5 h-2.5 rounded-full bg-rose-500 animate-ping"></span>
                            <span>🔴 ร้านนี้พักรับออเดอร์ชั่วคราว</span>
                        </span>
                        <span class="text-[10px] text-rose-600 font-normal">เปิดรับออเดอร์อีกครั้งเร็วๆ นี้</span>
                    </div>
                ` : ''}

                <!-- Products Header Banner with "ดูเพิ่มเติม" Button (แสดงเฉพาะเมื่อมีสินค้าเพิ่มเติมในข้อ 4) -->
                <div class="px-3.5 pt-0.5 flex items-center justify-between">
                    <span class="text-xs font-bold text-slate-800 flex items-center gap-1.5">
                        <span class="material-symbols-outlined text-sm text-orange-500">grid_view</span>
                        สินค้าสดแนะนำ (${stallProducts.length} รายการ)
                    </span>
                    ${hasExtraCatalog ? `
                        <button onclick="openStallCatalogModal('${stall.stallId}')" class="text-[11px] bg-emerald-50 hover:bg-emerald-100 text-emerald-800 font-extrabold px-2.5 py-1 rounded-xl border border-emerald-300/80 flex items-center gap-1 transition-all active:scale-95 shadow-xs">
                            <span class="material-symbols-outlined text-xs text-emerald-600">list_alt</span>
                            <span>ดูเพิ่มเติม (${extraItemsCount} รายการ)</span>
                            <span class="material-symbols-outlined text-xs">chevron_right</span>
                        </button>
                    ` : ''}
                </div>

                <!-- Products Single Column List (เรียงต่อกันเป็นบรรทัด: ลำดับ / ชื่อสินค้า / หน่วย / ราคา / สัญลักษณ์ตะกร้า) -->
                <div class="flex flex-col gap-1.5 px-3.5">
                    ${(!stallProducts || !Array.isArray(stallProducts) || stallProducts.length === 0) ? `
                        <div class="py-6 px-4 bg-slate-50/90 border border-dashed border-emerald-300/80 rounded-2xl text-center space-y-2">
                            <div class="w-10 h-10 rounded-full bg-emerald-100 text-emerald-700 flex items-center justify-center mx-auto text-lg font-bold">🏪</div>
                            <p class="text-xs font-bold text-slate-800">แผงค้าใหม่กำลังเตรียมรายการสินค้าลงระบบ</p>
                            <p class="text-[11px] text-slate-500">สามารถโทรติดต่อสอบถามหรือสั่งซื้อตรงได้ที่ <a href="tel:${phoneNum}" class="text-emerald-700 font-black underline">${phoneNum}</a></p>
                            ${(state.activeMerchant && state.activeMerchant.stallId === stall.stallId) ? `
                                <div class="pt-1">
                                    <button onclick="openActiveStallEditor()" class="px-3 py-1.5 bg-emerald-600 hover:bg-emerald-700 text-white font-bold rounded-xl text-xs shadow-sm inline-flex items-center gap-1 cursor-pointer active:scale-95 transition-all">
                                        <span class="material-symbols-outlined text-xs">edit_note</span>
                                        <span>แก้ไขและลงรายการสินค้าของคุณ</span>
                                    </button>
                                </div>
                            ` : ''}
                        </div>
                    ` : `
                        <!-- Column Header -->
                        <div class="flex items-center justify-between text-[10px] font-extrabold text-slate-400 px-3 pb-0.5 select-none">
                            <span class="w-5 shrink-0 text-center">ลำดับ</span>
                            <span class="flex-1 min-w-0 pl-1.5">ชื่อรายการสินค้า</span>
                            <div class="flex items-center gap-1.5 shrink-0">
                                <span class="w-9 text-center">หน่วย</span>
                                <span class="w-12 text-right">ราคา</span>
                            </div>
                            <span class="w-7 text-center shrink-0"></span>
                        </div>

                        ${stallProducts.map((product, idx) => {
                            const inCart = state.cart.find(item => item.productId === product.id);
                            const qtyInCart = inCart ? inCart.qty : 0;

                            return `
                                <div class="bg-white hover:bg-slate-50/90 rounded-xl py-1 px-2.5 sm:px-3 border ${qtyInCart > 0 ? 'border-emerald-500 bg-emerald-50/20 ring-1 ring-emerald-400 shadow-sm' : 'border-slate-200/90 shadow-2xs'} flex items-center justify-between gap-2 transition-all min-h-0">
                                    <!-- 1. ลำดับ -->
                                    <span class="w-5 h-5 rounded-md ${qtyInCart > 0 ? 'bg-emerald-600 text-white' : 'bg-slate-100 text-slate-700 font-black'} text-[11px] flex items-center justify-center shrink-0 leading-none">
                                        ${idx + 1}
                                    </span>

                                    <!-- 2. ชื่อรายการสินค้า -->
                                    <div class="flex-1 min-w-0 flex items-center gap-1.5 pl-1 leading-none">
                                        <span class="font-extrabold text-xs sm:text-sm text-slate-900 truncate leading-snug" title="${product.name}">
                                            ${product.name}
                                        </span>
                                        ${product.badge ? `
                                            <span class="text-[8px] font-extrabold text-orange-600 bg-orange-50 border border-orange-200 px-1 py-0.2 rounded shrink-0 hidden sm:inline-block leading-none">
                                                ${product.badge}
                                            </span>
                                        ` : ''}
                                    </div>

                                    <!-- 3 & 4. หน่วย + ราคา ขยับเข้ามาชิดกันมากที่สุด -->
                                    <div class="flex items-center gap-1.5 shrink-0">
                                        <!-- 3. หน่วย -->
                                        <span class="w-9 text-center text-[10px] sm:text-[11px] font-bold text-slate-500 bg-slate-100/90 px-1 py-0.5 rounded shrink-0 whitespace-nowrap leading-none">
                                            ${product.unit || 'กก.'}
                                        </span>

                                        <!-- 4. ราคา -->
                                        <div class="w-12 font-black text-xs sm:text-sm text-orange-600 shrink-0 text-right whitespace-nowrap leading-none">
                                            ฿${product.price}
                                        </div>
                                    </div>

                                    <!-- 5. สัญลักษณ์ตะกร้า -->
                                    <div class="w-7 shrink-0 flex items-center justify-center">
                                        ${qtyInCart > 0 ? `
                                            <!-- เมื่อหยิบใส่แล้ว: แสดงปุ่มปรับจำนวนสีเขียวขนาดกะทัดรัด -->
                                            <div class="flex items-center gap-0.5 bg-emerald-600 text-white rounded-lg px-1 py-0.5 text-[10px] shadow-sm ring-1 ring-emerald-400 h-6">
                                                <button type="button" onclick="changeCartQty('${product.id}', -1)" class="w-3.5 h-3.5 flex items-center justify-center hover:bg-emerald-700 active:scale-90 rounded font-black text-[10px] transition-transform cursor-pointer" title="ลดจำนวน">-</button>
                                                <span class="px-0.5 text-[10px] font-black min-w-[8px] text-center leading-none">${qtyInCart}</span>
                                                <button type="button" onclick="changeCartQty('${product.id}', 1)" class="w-3.5 h-3.5 flex items-center justify-center hover:bg-emerald-700 active:scale-90 rounded font-black text-[10px] transition-transform cursor-pointer" title="เพิ่มจำนวน">+</button>
                                            </div>
                                        ` : `
                                            <!-- ปุ่มสัญลักษณ์ตะกร้าสีส้มขนาดกะทัดรัด -->
                                            <button type="button" onclick="addToCart('${stall.stallId}', '${product.id}')" class="w-6 h-6 rounded-lg bg-orange-500 hover:bg-orange-600 active:scale-95 text-white flex items-center justify-center shadow-xs transition-all cursor-pointer shrink-0" title="เพิ่ม ${product.name} ลงตะกร้า">
                                                <span class="material-symbols-outlined text-[15px] font-bold">shopping_cart</span>
                                            </button>
                                        `}
                                    </div>
                                </div>
                            `;
                        }).join("")}
                    `}
                </div>

                ${hasExtraCatalog ? `
                    <!-- Bottom Full-Width "ดูเพิ่มเติม" Action Button (แสดงเฉพาะเมื่อมีสินค้าเพิ่มเติมในข้อ 4) -->
                    <div class="px-3.5 pt-1">
                        <button onclick="openStallCatalogModal('${stall.stallId}')" class="w-full py-2.5 bg-gradient-to-r from-emerald-50 via-teal-50 to-emerald-100/70 hover:from-emerald-100 hover:to-teal-100 border border-emerald-300/80 rounded-xl text-emerald-900 font-extrabold text-xs flex items-center justify-center gap-1.5 shadow-xs hover:shadow transition-all active:scale-[0.99]">
                            <span class="material-symbols-outlined text-base text-emerald-700">menu_book</span>
                            <span>ดูเพิ่มเติม: ตารางรายการสินค้าทั้งหมดของแผงนี้ (${extraItemsCount} รายการ)</span>
                            <span class="material-symbols-outlined text-sm text-emerald-600">chevron_right</span>
                        </button>
                    </div>
                ` : ''}
            </div>
        `;
    });

    container.innerHTML = html;
    updateStallRotationUI();
    if (typeof initStallBannerCarousels === "function") initStallBannerCarousels();
}

// ==========================================
// DYNAMIC FAVORITE STALLS BAR & PERSISTENCE
// ==========================================
function renderFavoriteStallsBar() {
    const container = document.getElementById("favorite-stalls-list");
    if (!container) return;

    if (!state.favorites || state.favorites.length === 0) {
        container.innerHTML = `
            <span class="text-amber-800/80 text-[11px] font-medium py-1 px-2 whitespace-nowrap italic">
                ยังไม่มีร้านโปรด แตะปุ่ม "⭐ บันทึกร้านโปรด" ที่หน้าร้านค้า
            </span>
        `;
        return;
    }

    let html = "";
    state.favorites.slice(0, 5).forEach(stallId => {
        const stall = ALL_100_STALLS.find(s => s.stallId === stallId) || MARKET_DATA.find(s => s.stallId === stallId);
        if (!stall) return;

        let colorClass = "bg-white hover:bg-amber-50 text-slate-800 border-amber-200";
        if (stall.category === "chicken") colorClass = "bg-white hover:bg-orange-50 text-orange-950 border-orange-200";
        else if (stall.category === "veggie") colorClass = "bg-white hover:bg-emerald-50 text-emerald-950 border-emerald-200";
        else if (stall.category === "pork") colorClass = "bg-white hover:bg-pink-50 text-pink-950 border-pink-200";
        else if (stall.category === "curry") colorClass = "bg-white hover:bg-red-50 text-red-950 border-red-200";
        else if (stall.category === "seafood") colorClass = "bg-white hover:bg-cyan-50 text-cyan-950 border-cyan-200";

        const isCurrentlySelected = state.currentSingleStall === stallId;
        const activeRing = isCurrentlySelected ? "ring-2 ring-amber-500 bg-amber-50 font-extrabold" : "font-bold";

        // Emoji extraction
        const emoji = stall.stallTag ? stall.stallTag.split(" ")[0] : "🏪";
        const shortName = stall.stallName.replace("แผง", "").replace("ร้าน", "").trim();

        html += `
            <button onclick="filterBySingleStall('${stall.stallId}')" class="${colorClass} ${activeRing} border px-2.5 py-1 rounded-xl whitespace-nowrap text-[11px] flex items-center gap-1 shadow-xs shrink-0 active:scale-95 transition-all" title="${stall.stallName}">
                <span>${emoji}</span>
                <span>${stall.stallNumber} (${shortName})</span>
            </button>
        `;
    });

    container.innerHTML = html;
}

// Toggle Favorite Stall (Max 5 Stalls Saved in LocalStorage)
function toggleFavoriteStall(stallId) {
    const stall = ALL_100_STALLS.find(s => s.stallId === stallId) || MARKET_DATA.find(s => s.stallId === stallId);
    const stallName = stall ? stall.stallName : "ร้านค้า";

    if (!state.favorites) state.favorites = [];
    const idx = state.favorites.indexOf(stallId);

    if (idx >= 0) {
        state.favorites.splice(idx, 1);
        showToast(`นำ "${stallName}" ออกจากร้านโปรดแล้ว`);
    } else {
        if (state.favorites.length >= 5) {
            // Keep maximum 5 favorites (remove oldest)
            state.favorites.shift();
        }
        state.favorites.push(stallId);
        showToast(`⭐ บันทึก "${stallName}" เป็นร้านโปรดแล้ว!`);
    }

    saveFavoritesToStorage(state.favorites);
    renderFavoriteStallsBar();
    renderCatalog();
}

function filterByCategory(category) {
    state.currentCategoryFilter = category;
    state.currentSingleStall = null;

    document.querySelectorAll(".cat-pill").forEach(pill => pill.classList.remove("active", "bg-emerald-700", "text-white"));
    const activeBtn = (typeof event !== 'undefined' && event && event.currentTarget) ? event.currentTarget : document.querySelector(`.cat-pill[onclick*="${category}"]`);
    if (activeBtn) activeBtn.classList.add("active", "bg-emerald-700", "text-white");

    selectRandomStallBatch();
    state.stallRotation.remainingSeconds = state.stallRotation.intervalSeconds;

    renderFavoriteStallsBar();
    renderCatalog();
    updateStallRotationUI();
}

