const DEFAULT_COMMUNITY_RIDERS = [];

// Mock sample IDs to remove legacy dummy data
const MOCK_COMMUNITY_RIDER_IDS = ["RIDER-001", "RIDER-002", "RIDER-003", "RIDER-004"];
const MOCK_RIDER_APP_IDS = ["APP-RD-101"];

function isMockCommunityRider(r) {
    if (!r) return true;
    if (r.isMock) return true;
    if (r.id && (MOCK_COMMUNITY_RIDER_IDS.includes(r.id) || r.id === "RIDER-8923")) return true;
    if (r.name && (r.name.includes("ใจ มุ่งมั่น") || r.name.includes("ไว มุ่งมั่น"))) return true;
    if (r.phone && r.phone.replace(/[-\s]/g, "") === "0815887400") return true;
    return false;
}

function isMockRiderApplication(a) {
    if (!a) return true;
    if (a.isMock === true) return true;
    return false;
}

function loadCommunityRiders() {
    try {
        const raw = localStorage.getItem("talathub_community_riders");
        if (raw) {
            const parsed = JSON.parse(raw);
            if (Array.isArray(parsed)) {
                return parsed.filter(r => r && !isMockCommunityRider(r));
            }
        }
    } catch (e) {
        console.error("Error loading community riders:", e);
    }
    return [];
}

function saveCommunityRiders(list) {
    try {
        const cleaned = (list || []).filter(r => r && !isMockCommunityRider(r));
        localStorage.setItem("talathub_community_riders", JSON.stringify(cleaned));
        if (isFirebaseReady() && db) {
            db.ref("community_riders").set(cleaned).catch(err => {
                console.warn("Firebase save community_riders failed:", err);
            });
        }
    } catch (e) {
        console.error("Error saving community riders:", e);
    }
}

// ── Rider Applications Management (ใบสมัครไรเดอร์ส่งของสด)
function loadRiderApplications() {
    try {
        const raw = localStorage.getItem("talathub_rider_applications");
        if (raw) {
            const parsed = JSON.parse(raw);
            if (Array.isArray(parsed)) {
                return parsed.filter(a => a && !isMockRiderApplication(a));
            }
        }
    } catch (e) {
        console.error("Error loading rider applications:", e);
    }
    return [];
}

function saveRiderApplications(apps) {
    try {
        const cleaned = (apps || []).filter(a => a && !isMockRiderApplication(a));
        localStorage.setItem("talathub_rider_applications", JSON.stringify(cleaned));
        if (isFirebaseReady() && db) {
            db.ref("rider_applications").set(cleaned).catch(err => {
                console.warn("Firebase save rider_applications failed:", err);
            });
        }
    } catch (e) {
        console.error("Error saving rider applications:", e);
    }
}

// ── Realtime Firebase Sync for Riders & Applications
let _isRiderSyncInitialized = false;

function initRiderRealtimeSync() {
    if (!isFirebaseReady() || _isRiderSyncInitialized) return;
    _isRiderSyncInitialized = true;

    // 1. Sync Rider Applications from Firebase
    db.ref("rider_applications").on("value", snapshot => {
        try {
            const data = snapshot.val();
            let rawList = [];
            if (Array.isArray(data)) {
                rawList = data.filter(Boolean);
            } else if (data && typeof data === "object") {
                rawList = Object.values(data).filter(Boolean);
            }

            const cleaned = rawList.filter(a => a && !isMockRiderApplication(a));
            localStorage.setItem("talathub_rider_applications", JSON.stringify(cleaned));
            updateAdminRiderBadges();

            if (state.currentRole === "admin") {
                if (_activeAdminTab === "riders") {
                    renderAdminRiders();
                } else if (_activeAdminTab === "report") {
                    renderAdminReport();
                }
            }
        } catch (err) {
            console.warn("Error syncing rider_applications:", err);
        }
    });

    // 2. Sync Community Riders from Firebase
    db.ref("community_riders").on("value", snapshot => {
        try {
            const data = snapshot.val();
            let rawList = [];
            if (Array.isArray(data)) {
                rawList = data.filter(Boolean);
            } else if (data && typeof data === "object") {
                rawList = Object.values(data).filter(Boolean);
            }

            const cleaned = rawList.filter(r => r && !isMockCommunityRider(r));
            localStorage.setItem("talathub_community_riders", JSON.stringify(cleaned));

            if (state.currentRole === "admin" && _activeAdminTab === "riders") {
                renderAdminRiders();
            }
            checkCurrentRiderApprovalRealtime(cleaned);
        } catch (err) {
            console.warn("Error syncing community_riders:", err);
        }
    });
}
window.initRiderRealtimeSync = initRiderRealtimeSync;

let _isMerchantSyncInitialized = false;

function initMerchantRealtimeSync() {
    if (!isFirebaseReady() || _isMerchantSyncInitialized) return;
    _isMerchantSyncInitialized = true;

    db.ref("merchant_applications").on("value", snapshot => {
        try {
            const data = snapshot.val();
            let rawList = [];
            if (Array.isArray(data)) {
                rawList = data.filter(Boolean);
            } else if (data && typeof data === "object") {
                rawList = Object.values(data).filter(Boolean);
            }

            localStorage.setItem("talathub_merchant_applications", JSON.stringify(rawList));
            updateAdminStallsBadge();

            // Sync approved stalls into MARKET_DATA and ALL_100_STALLS across all online clients
            rawList.forEach(app => {
                if (app && app.status === "approved" && app.stallData) {
                    const sData = { ...app.stallData, accessCode: app.accessCode || app.stallData.accessCode };
                    const mIdx = MARKET_DATA.findIndex(s => s.stallId === sData.stallId);
                    if (mIdx >= 0) {
                        MARKET_DATA[mIdx] = { ...MARKET_DATA[mIdx], ...sData };
                    } else {
                        MARKET_DATA.push(sData);
                    }
                    if (typeof ALL_100_STALLS !== "undefined" && Array.isArray(ALL_100_STALLS)) {
                        const aIdx = ALL_100_STALLS.findIndex(s => s.stallId === sData.stallId);
                        if (aIdx >= 0) {
                            ALL_100_STALLS[aIdx] = { ...ALL_100_STALLS[aIdx], ...sData };
                        } else {
                            ALL_100_STALLS.push(sData);
                        }
                    }
                    if (sData.catalog && Array.isArray(sData.catalog)) {
                        STALL_CATALOG_DATABASE[sData.stallId] = sData.catalog;
                    }
                }
            });

            if (typeof renderCatalog === "function") renderCatalog();
            if (typeof renderDirectoryList === "function") renderDirectoryList();
            if (typeof renderFavoriteStallsBar === "function") renderFavoriteStallsBar();
            if (typeof updateStallRotationUI === "function") updateStallRotationUI();
            if (state.currentRole === "merchant" && typeof renderMerchantView === "function") {
                renderMerchantView();
            }

            if (state.currentRole === "admin") {
                if (_activeAdminTab === "stalls") {
                    renderAdminStalls();
                } else if (_activeAdminTab === "report") {
                    renderAdminReport();
                }
            }
        } catch (err) {
            console.warn("Error syncing merchant_applications:", err);
        }
    });
}
window.initMerchantRealtimeSync = initMerchantRealtimeSync;

function updateAdminRiderBadges() {
    const apps = loadRiderApplications();
    const pendingCount = apps.filter(a => a.status === "pending").length;

    // Badge on Admin Tab (แท็บ 4. จัดการไรเดอร์ & ค่ารอบ)
    const tabBadge = document.getElementById("admin-riders-badge");
    if (tabBadge) {
        if (pendingCount > 0) {
            tabBadge.textContent = `${pendingCount} รออนุมัติ`;
            tabBadge.className = "ml-1 px-1.5 py-0.5 text-[10px] font-black bg-amber-500 text-slate-950 rounded-full animate-pulse shadow-xs";
            tabBadge.classList.remove("hidden");
        } else {
            tabBadge.classList.add("hidden");
        }
    }

    // Badge on Main Navigation Bar (ปุ่ม 5. แอดมิน)
    const roleBadge = document.getElementById("role-admin-badge");
    if (roleBadge) {
        if (pendingCount > 0) {
            roleBadge.classList.remove("hidden");
        } else {
            roleBadge.classList.add("hidden");
        }
    }
}
