        { name: "อนุสรณ์ ขยันส่ง", nick: "บอย", phone: "092-333-8899", model: "Honda PCX 160", plate: "3ขข-7711 ระยอง", bank: "กรุงไทย", shifts: ["ทั้งวัน (05:00 - 18:30)"] }
