function renderHubSettlement() {
    const container = document.getElementById("hub-content-settlement");
    if (!container) return;

    const order = state.activeOrder;
    let expressOrders = (state.merchantExpressOrders || []).slice();
    if (expressOrders.length === 0) {
        try {
            expressOrders = JSON.parse(localStorage.getItem("hsong_merchant_express_orders") || "[]");
        } catch(e) {}
    }

    const hasGrocery = !!(order && order.stalls && order.stalls.length > 0);
    const hasExpress = expressOrders.length > 0;

    if (!hasGrocery && !hasExpress) {
        container.innerHTML = `
            <div class="bg-white rounded-3xl p-8 text-center border border-slate-200 shadow-sm space-y-2">
                <div class="text-3xl">💰</div>
                <h4 class="font-bold text-sm text-slate-700">ยังไม่มีรายการยอดเคลียร์เงิน</h4>
                <p class="text-[11px] text-slate-500">ยอดเงินเคลียร์แผงค้าและค่ารอบไรเดอร์จะคำนวณอัตโนมัติตามสินค้าและงานที่เกิดขึ้นจริง</p>
            </div>
        `;
        return;
    }

    let html = "";

    // 1. สรุปยอดจ่ายแผงค้า (Grocery Orders)
    if (hasGrocery) {
        let vendorListHtml = "";
        let vendorTotal = 0;
        order.stalls.forEach(stall => {
            const activeItems = (stall.items || []).filter(item => !item.outOfStock);
            const oosItems = (stall.items || []).filter(item => item.outOfStock);
            const stallItemsTotal = activeItems.reduce((sum, item) => sum + (item.actualPrice !== undefined ? item.actualPrice : item.price), 0);
            vendorTotal += stallItemsTotal;

            vendorListHtml += `
                <div class="flex justify-between items-center p-3 bg-slate-50 rounded-2xl border border-slate-200/80">
                    <div>
                        <div class="font-bold text-slate-800 text-xs">${stall.name}</div>
                        <div class="text-[10px] text-slate-500">
                            หยิบจริง ${activeItems.length} รายการ ${oosItems.length > 0 ? `<span class="text-rose-600 font-bold">(หมด ${oosItems.length})</span>` : ''}
                        </div>
                    </div>
                    <div class="text-right">
                        <div class="font-black text-emerald-700 text-xs">฿${stallItemsTotal}</div>
                        <button type="button" onclick="clearHubSettlementVendor('${stall.name.replace(/'/g, "\\'")}', this)" class="text-[10px] bg-emerald-600 hover:bg-emerald-700 active:scale-95 text-white px-2.5 py-1 rounded-lg font-bold mt-1 shadow-xs transition-all cursor-pointer">โอนเคลียร์เงิน</button>
                    </div>
                </div>
            `;
        });

        html += `
            <div class="bg-white rounded-3xl p-4 shadow-card border border-slate-200 space-y-3 mb-4 text-left">
                <div class="flex items-center justify-between pb-2 border-b border-slate-100">
                    <h3 class="font-bold text-sm text-slate-800 flex items-center gap-1">
                        <span class="material-symbols-outlined text-emerald-700 text-base">account_balance_wallet</span>
                        <span>สรุปยอดจ่ายแผงค้า (${order.orderId})</span>
                    </h3>
                    <span class="text-[11px] text-slate-500 font-medium">รวม ฿${vendorTotal}</span>
                </div>
                <div class="space-y-2">
                    ${vendorListHtml}
                </div>
            </div>

            <div class="bg-gradient-to-r from-emerald-800 to-slate-900 text-white rounded-3xl p-4 shadow-card space-y-2 mb-4 text-left">
                <div class="text-xs text-emerald-300 font-bold">รายรับรวมระบบจัดส่ง (ค่าสินค้า + ค่าบริการรวมบิล + ค่าส่ง)</div>
                <div class="text-2xl font-black">฿${order.grandTotal || order.total || 185} <span class="text-xs font-normal text-slate-300">บาท</span></div>
                <div class="text-[11px] text-slate-300 flex justify-between pt-2 border-t border-slate-700">
                    <span>ยอดรวมร้านค้า: ฿${vendorTotal}</span>
                    <span>ค่าส่ง+บริการรวมแผง: ฿${Math.max(20, (order.grandTotal || order.total || 185) - vendorTotal)}</span>
                </div>
            </div>
        `;
    }

    // 2. สรุปยอดเคลียร์งานด่วนแผงค้า (Express Orders Settlement)
    if (hasExpress) {
        let expressRows = "";
        let expressFeeTotal = 0;
        expressOrders.forEach((exp) => {
            const fee = Number(exp.deliveryFee || 20);
            expressFeeTotal += fee;
            const rider = exp.assignedRider || { name: "กำลังจัดสรร", phone: "-" };
            expressRows += `
                <div class="flex justify-between items-center p-3 bg-orange-50/60 rounded-2xl border border-orange-200">
                    <div class="space-y-0.5">
                        <div class="font-extrabold text-slate-900 text-xs flex items-center gap-1.5">
                            <span>⚡ ${exp.orderId}</span>
                            <span class="text-[10px] text-orange-800 font-bold bg-orange-100 px-2 py-0.2 rounded-full">${exp.originStall?.stallName || 'แผงค้า'}</span>
                        </div>
                        <div class="text-[10px] text-slate-600">
                            🛵 ไรเดอร์: <strong>${rider.name}</strong> • ผู้รับ: คุณ${exp.customerName || 'ลูกค้า'}
                        </div>
                    </div>
                    <div class="text-right shrink-0">
                        <div class="font-black text-emerald-700 text-xs">฿${fee}</div>
                        <button type="button" onclick="clearHubSettlementVendor('ไรเดอร์: ${rider.name.replace(/'/g, "\\'")} (งาน ${exp.orderId})', this)" class="text-[10px] bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-700 hover:to-teal-700 active:scale-95 text-white px-2.5 py-1 rounded-lg font-bold mt-1 shadow-xs transition-all cursor-pointer">
                            โอนให้ไรเดอร์
                        </button>
                    </div>
                </div>
            `;
        });

        html += `
            <div class="bg-white rounded-3xl p-4 shadow-card border border-orange-200 space-y-3 text-left">
                <div class="flex items-center justify-between pb-2 border-b border-orange-100">
                    <h3 class="font-bold text-sm text-orange-950 flex items-center gap-1">
                        <span class="material-symbols-outlined text-orange-600 text-base">two_wheeler</span>
                        <span>สรุปยอดเคลียร์ค่ารอบงานด่วน (Express Fleet Settlement)</span>
                    </h3>
                    <span class="text-[11px] text-orange-700 font-bold">รวมค่าส่ง ฿${expressFeeTotal}</span>
                </div>
                <div class="space-y-2">
                    ${expressRows}
                </div>
            </div>
        `;
    }

    container.innerHTML = html;
}

function clearHubSettlementVendor(vendorName, btn = null) {
    if (btn) {
        btn.disabled = true;
        btn.className = "text-[10px] bg-slate-200 text-slate-500 px-2.5 py-1 rounded-lg font-bold mt-1 cursor-default";
        btn.textContent = "✓ โอนแล้ว";
    }
    showToast(`✓ โอนเงินผ่าน PromptPay เคลียร์ยอดให้ "${vendorName}" สำเร็จแล้ว!`);
}

function renderRiderScreen() {
    const order = state.activeOrder;
    const badge = document.getElementById("rider-order-id-badge");
    const totalBadge = document.getElementById("rider-order-total-badge");
    const destName = document.getElementById("rider-dest-name");
    const destDetail = document.getElementById("rider-dest-detail");
    const noteText = document.getElementById("rider-note-text");
    const mapsLink = document.getElementById("rider-maps-link");
    const statusBadge = document.getElementById("rider-current-status-badge");
    const refundAlert = document.getElementById("rider-refund-alert");
    const refundAmount = document.getElementById("rider-refund-alert-amount");
    const btnStart = document.getElementById("btn-rider-start-delivery");
    const btnStartText = document.getElementById("rider-btn-start-text");
    const btnStartIcon = document.getElementById("rider-btn-start-icon");
    const btnComplete = document.getElementById("btn-rider-complete-delivery");
    const btnCompleteText = document.getElementById("rider-btn-complete-text");
    const btnCompleteIcon = document.getElementById("rider-btn-complete-icon");
    const completedBanner = document.getElementById("rider-completed-banner");

    if (!order) {
        if (badge) badge.textContent = "ไม่มีงานค้าง";
        if (totalBadge) totalBadge.textContent = "฿0";
        if (destName) destName.textContent = "รอรับออเดอร์ใหม่จากฮับ";
        if (destDetail) {
            destDetail.innerHTML = `
                <div class="space-y-2">
                    <div>ขณะนี้ไม่มีคิวจัดส่งที่มอบหมายให้คุณ</div>
                    <button onclick="assignSampleOrderToRider()" class="px-3 py-1.5 bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-700 hover:to-teal-700 text-white font-bold rounded-xl text-xs shadow-md flex items-center gap-1.5 active:scale-95 transition-all">
                        <span class="material-symbols-outlined text-xs">local_shipping</span>
                        <span>📦 รับงานส่งของสดตัวอย่างเข้าสู่ระบบรับงาน</span>
                    </button>
                </div>
            `;
        }
        if (noteText) noteText.textContent = "-";
        const destHouse = document.getElementById("rider-dest-house");
        const destSubdistrict = document.getElementById("rider-dest-subdistrict");
        const phoneBadge = document.getElementById("rider-phone-badge");
        const gpsCoords = document.getElementById("rider-gps-coords");
        if (destHouse) destHouse.textContent = "รอระบุที่อยู่จัดส่ง";
        if (destSubdistrict) destSubdistrict.textContent = "อำเภอบ้านบึง จังหวัดชลบุรี";
        if (phoneBadge) phoneBadge.textContent = "-";
        if (gpsCoords) gpsCoords.textContent = "-";
        if (statusBadge) {
            statusBadge.className = "text-[10px] font-bold px-2 py-0.5 rounded-full bg-slate-100 text-slate-600";
            statusBadge.textContent = "พร้อมรับงาน";
        }
        if (refundAlert) refundAlert.classList.add("hidden");
        if (completedBanner) completedBanner.classList.add("hidden");
        return;
    }

    const destHouse = document.getElementById("rider-dest-house");
    const destSubdistrict = document.getElementById("rider-dest-subdistrict");
    const phoneBadge = document.getElementById("rider-phone-badge");
    const gpsCoords = document.getElementById("rider-gps-coords");
    const callBtnText = document.getElementById("rider-call-btn-text");

    const orderLat = order.lat || (state.deliveryLocation && state.deliveryLocation.lat) || MARKET_ORIGIN.lat;
    const orderLng = order.lng || (state.deliveryLocation && state.deliveryLocation.lng) || MARKET_ORIGIN.lng;
    const orderPhone = order.customerPhone || (state.customer && state.customer.phone) || "-";

    const callMerchantBtn = document.getElementById("rider-call-merchant-btn");
    const callMerchantText = document.getElementById("rider-call-merchant-text");

    if (order.orderType === "MERCHANT_EXPRESS") {
        const origin = order.originStall || {};
        if (badge) badge.textContent = `⚡ งานด่วน ${order.orderId}`;
        if (totalBadge) totalBadge.textContent = `฿${order.deliveryFee || 20} (ค่าจัดส่ง)`;
        if (destName) destName.textContent = `${order.customerName || 'ลูกค้า'} (จาก: ${origin.stallName || 'แผงค้า'})`;
        if (phoneBadge) phoneBadge.textContent = orderPhone;
        if (callBtnText) callBtnText.textContent = `โทรหาลูกค้า (${orderPhone})`;
        if (destDetail) destDetail.textContent = `🏪 รับของที่: ${origin.stallName || 'แผงค้า'} (${origin.stallNumber || 'แผงค้า'}) โทร ${origin.ownerPhone || '-'} | 📍 ส่ง: ${order.address}`;
        if (noteText) noteText.textContent = `พัสดุ: ร้านค้าแพ็คเรียบร้อยแล้ว • ค่าจัดส่ง ฿${order.deliveryFee || 20} (ไม่มีบริการ COD)`;

        if (callMerchantBtn) {
            callMerchantBtn.classList.remove("hidden");
            if (callMerchantText) callMerchantText.textContent = `โทรหาแผงค้า (${origin.ownerPhone || '-'})`;
        }
    } else {
        if (badge) badge.textContent = `ออเดอร์ ${order.orderId}`;
        if (totalBadge) totalBadge.textContent = `฿${order.grandTotal || order.total || 0} (${order.paymentDesc || 'ชำระแล้ว'})`;
        if (destName) destName.textContent = order.customerName || "ลูกค้าประจำ";
        if (phoneBadge) phoneBadge.textContent = orderPhone;
        if (callBtnText) callBtnText.textContent = `โทรหาลูกค้า (${orderPhone})`;
        if (destDetail) destDetail.textContent = `ที่อยู่: ${order.address || 'ตามพิกัดที่ลูกค้าระบุ'}`;
        if (noteText) noteText.textContent = order.landmark || order.deliveryNote || "-";
        if (callMerchantBtn) callMerchantBtn.classList.add("hidden");
    }

    if (destHouse) {
        if (order.houseNumber) {
            destHouse.textContent = `${order.houseNumber} ${order.soiRoad || ''}`.trim();
        } else {
            destHouse.textContent = order.address || "ตามพิกัดดาวเทียม";
        }
    }
    if (destSubdistrict) {
        destSubdistrict.textContent = order.subdistrict || "อำเภอบ้านบึง จังหวัดชลบุรี";
    }
    if (gpsCoords) gpsCoords.textContent = `${Number(orderLat).toFixed(6)}, ${Number(orderLng).toFixed(6)}`;

    // Direct Turn-by-Turn GPS navigation link into Google Maps
    if (mapsLink) {
        mapsLink.href = `https://www.google.com/maps/dir/?api=1&destination=${orderLat},${orderLng}`;
    }

    // Check Refund Amount (กรณีมีสินค้าขาด)
    let refundCashTotal = order.refundCashTotal || 0;
    if (refundCashTotal === 0 && order.stalls) {
        order.stalls.forEach(s => {
            (s.items || []).forEach(it => {
                if (it.outOfStock) {
                    refundCashTotal += (it.actualPrice !== undefined ? it.actualPrice : it.price);
                }
            });
        });
        order.refundCashTotal = refundCashTotal;
    }

    if (refundAlert) {
        if (refundCashTotal > 0 && order.status !== "delivered") {
            refundAlert.classList.remove("hidden");
            if (refundAmount) refundAmount.textContent = `฿${refundCashTotal}`;
        } else {
            refundAlert.classList.add("hidden");
        }
    }

    // Dynamic Button States based on order.status
    const status = order.status || "picking";

    if (status === "delivering") {
        if (statusBadge) {
            statusBadge.className = "text-[10px] font-bold px-2 py-0.5 rounded-full bg-blue-100 text-blue-800 animate-pulse";
            statusBadge.textContent = "🛵 กำลังออกส่ง";
        }
        if (btnStart) {
            btnStart.className = "p-3 bg-emerald-50 text-emerald-800 border border-emerald-300 font-bold rounded-xl shadow-xs flex items-center justify-center gap-1 text-xs active:scale-95 transition-all";
        }
        if (btnStartText) btnStartText.textContent = `✓ รับของแล้ว (${order.startedDeliveryAt || 'กำลังส่ง'})`;
        if (btnStartIcon) btnStartIcon.textContent = "check";

        if (btnComplete) {
            btnComplete.className = "p-3 bg-emerald-700 hover:bg-emerald-800 text-white font-extrabold rounded-xl shadow-md flex items-center justify-center gap-1 text-xs ring-2 ring-emerald-400 ring-offset-2 animate-pulse active:scale-95 transition-all";
        }
        if (btnCompleteText) {
            btnCompleteText.textContent = "2. ส่งมอบสำเร็จ (แตะเมื่อถึง)";
        }
        if (btnCompleteIcon) btnCompleteIcon.textContent = "check_circle";

        if (completedBanner) completedBanner.classList.add("hidden");

    } else if (status === "delivered") {
        if (statusBadge) {
            statusBadge.className = "text-[10px] font-bold px-2 py-0.5 rounded-full bg-emerald-100 text-emerald-800";
            statusBadge.textContent = "🎉 จัดส่งสำเร็จแล้ว";
        }
        if (btnStart) {
            btnStart.className = "p-3 bg-slate-100 text-slate-400 font-medium rounded-xl flex items-center justify-center gap-1 text-xs cursor-default";
        }
        if (btnStartText) btnStartText.textContent = "✓ รับของแล้ว";
        if (btnStartIcon) btnStartIcon.textContent = "check";

        if (btnComplete) {
            btnComplete.className = "p-3 bg-emerald-50 text-emerald-800 border border-emerald-300 font-bold rounded-xl flex items-center justify-center gap-1 text-xs cursor-default";
        }
        if (btnCompleteText) btnCompleteText.textContent = `✓ ส่งมอบสำเร็จแล้ว (${order.deliveredAt || '09:05 น.'})`;
        if (btnCompleteIcon) btnCompleteIcon.textContent = "verified";

        if (completedBanner) completedBanner.classList.remove("hidden");

    } else {
        // "picking" or initial status
        if (statusBadge) {
            statusBadge.className = "text-[10px] font-bold px-2 py-0.5 rounded-full bg-amber-100 text-amber-800";
            statusBadge.textContent = (order.orderType === "MERCHANT_EXPRESS") ? "📦 รับของที่หน้าแผงค้า" : "📦 รอรับของสดจากฮับ";
        }
        if (btnStart) {
            btnStart.className = "p-3 bg-amber-500 hover:bg-amber-600 text-white font-bold rounded-xl shadow-xs flex items-center justify-center gap-1 text-xs active:scale-95 transition-all";
        }
        if (btnStartText) {
            btnStartText.textContent = (order.orderType === "MERCHANT_EXPRESS") ? "1. ถึงแผงค้าและรับของแล้ว 🛵💨" : "1. รับของแล้ว ออกส่ง";
        }
        if (btnStartIcon) btnStartIcon.textContent = "two_wheeler";

        if (btnComplete) {
            btnComplete.className = "p-3 bg-slate-100 text-slate-400 font-bold rounded-xl shadow-xs flex items-center justify-center gap-1 text-xs active:scale-95 transition-all";
        }
        if (btnCompleteText) btnCompleteText.textContent = "2. ส่งมอบสำเร็จ";
        if (btnCompleteIcon) btnCompleteIcon.textContent = "check_circle";

        if (completedBanner) completedBanner.classList.add("hidden");
    }
}

function assignSampleOrderToRider() {
    createSampleCustomerOrder();
    if (!state.activeOrder) return;

    if (state.activeRider && state.activeRider.isLoggedIn) {
        state.activeOrder.riderName = state.activeRider.name;
        state.activeOrder.riderPhone = state.activeRider.phone;
    } else {
        const riders = loadCommunityRiders();
        if (riders && riders.length > 0) {
            state.activeOrder.riderName = riders[0].name;
            state.activeOrder.riderPhone = riders[0].phone;
        }
    }
    state.activeOrder.status = "picking";
    saveActiveOrderToStorage(state.activeOrder);

    setActiveRoleView("rider");
    renderRiderScreen();
    showToast("📦 มอบหมายออเดอร์ตัวอย่างเข้าคิวของไรเดอร์เรียบร้อย! คุณสามารถเริ่มกด '1. รับของแล้ว ออกส่ง' ได้ทันที");
}
window.assignSampleOrderToRider = assignSampleOrderToRider;

// Rider Login & Logout
function renderRiderLoginModalList() {
    const container = document.getElementById("rider-quick-login-list");
    if (!container) return;

    const riders = loadCommunityRiders();
    if (!riders || riders.length === 0) {
        container.innerHTML = `
            <div class="p-3 bg-slate-50 rounded-2xl border border-dashed border-slate-200 text-center text-slate-400 text-xs">
                <div>ยังไม่มีรายชื่อไรเดอร์ที่อนุมัติในระบบ</div>
                <button type="button" onclick="closeRiderLoginModal(); openRiderRegisterModal();" class="mt-1.5 text-sky-600 font-bold underline hover:text-sky-800 cursor-pointer">
                    + สมัครเป็นไรเดอร์ใหม่ทันที
                </button>
            </div>
        `;
        return;
    }

    let html = "";
    riders.forEach(r => {
        const code = r.accessCode || r.pin || r.id.slice(-6).toUpperCase();
        html += `
            <div class="flex items-center justify-between p-2.5 bg-slate-50 hover:bg-sky-50/80 rounded-2xl border border-slate-200 transition-all">
                <div class="flex items-center gap-2">
                    <div class="w-8 h-8 rounded-xl bg-sky-100 text-sky-800 flex items-center justify-center font-bold text-sm shrink-0">
                        🛵
                    </div>
                    <div class="text-left">
                        <div class="font-extrabold text-xs text-slate-900">${r.name}</div>
                        <div class="text-[10px] text-slate-500 font-mono">รหัส: <strong class="text-sky-700 font-bold">${code}</strong> • ทะเบียน: ${r.plate || '-'}</div>
                    </div>
                </div>
                <button type="button" onclick="loginRiderWithProfile(loadCommunityRiders().find(x => x.id === '${r.id}'))" class="px-3 py-1.5 bg-gradient-to-r from-sky-600 to-blue-600 hover:from-sky-700 hover:to-blue-700 text-white font-bold rounded-xl text-xs shadow-xs active:scale-95 transition-all cursor-pointer">
                    เข้าสู่ระบบ
                </button>
            </div>
        `;
    });
    container.innerHTML = html;
}
window.renderRiderLoginModalList = renderRiderLoginModalList;

function openRiderLoginModal() {
    const modal = document.getElementById("rider-login-modal");
    if (!modal) return;
    modal.classList.remove("hidden");

    renderRiderLoginModalList();

    const phoneInput = document.getElementById("rider-login-phone-input");
    if (phoneInput) {
        phoneInput.value = "";
        setTimeout(() => phoneInput.focus(), 100);
    }
}
window.openRiderLoginModal = openRiderLoginModal;

function closeRiderLoginModal() {
    const modal = document.getElementById("rider-login-modal");
    if (modal) modal.classList.add("hidden");
}
window.closeRiderLoginModal = closeRiderLoginModal;

function handleRiderLoginSubmit() {
    const riderSelect = document.getElementById("rider-select-input");
    const val = riderSelect ? riderSelect.value : "";
    if (!val) {
        showToast("⚠️ ยังไม่มีรายชื่อไรเดอร์ในระบบ กรุณาสมัครเป็นไรเดอร์ใหม่ด้านล่าง");
        return;
    }

    const riders = loadCommunityRiders();
    const r = riders.find(x => x.id === val);
    if (!r) {
        showToast("⚠️ ไม่พบข้อมูลไรเดอร์ที่เลือก");
        return;
    }

    loginRiderWithProfile(r);
}
window.handleRiderLoginSubmit = handleRiderLoginSubmit;

function handleRiderPhoneLoginSubmit() {
    const input = document.getElementById("rider-login-phone-input");
    const raw = input ? input.value.trim() : "";
    if (!raw) {
        showToast("⚠️ กรุณากรอกรหัสไรเดอร์ 6 หลัก หรือเบอร์โทรศัพท์");
        return;
    }

    const cleanRaw = raw.replace(/[-\s]/g, "");
    const upperRaw = cleanRaw.toUpperCase();

    const riders = loadCommunityRiders();

    // 1. ตรวจสอบในรายชื่อไรเดอร์ที่ได้รับการอนุมัติแล้ว (ตรวจทั้งรหัสผ่าน 6 หลัก, เบอร์โทร, หรือ ID)
    let r = riders.find(x => 
        (x.accessCode && x.accessCode.trim().toUpperCase() === upperRaw) ||
        (x.phone && x.phone.replace(/[-\s]/g, "") === cleanRaw) ||
        (x.id && x.id.trim().toUpperCase() === upperRaw)
    );
    if (r) {
        loginRiderWithProfile(r);
        return;
    }

    // 2. ตรวจสอบในข้อมูลใบสมัคร (Rider Applications)
    const apps = loadRiderApplications();
    const app = apps.find(x => 
        (x.accessCode && x.accessCode.trim().toUpperCase() === upperRaw) ||
        (x.phone && x.phone.replace(/[-\s]/g, "") === cleanRaw) ||
        (x.id && x.id.trim().toUpperCase() === upperRaw)
    );

    if (app) {
        if (app.status === "pending") {
            showToast(`⏳ ใบสมัครของคุณ (${app.fullName || raw}) อยู่ระหว่างรอแอดมินอนุมัติ กรุณารอการตรวจสอบสักครู่ครับ`);
            return;
        } else if (app.status === "rejected") {
            showToast(`❌ ใบสมัครของคุณ (${app.fullName || raw}) ไม่ผ่านการอนุมัติ สามารถสมัครใหม่หรือติดต่อแอดมินได้ครับ`);
            return;
        } else if (app.status === "approved") {
            // หากได้รับอนุมัติแล้วแต่ยังไม่มีข้อมูลใน community riders ให้ซิงค์ข้อมูลและล็อกอินทันที
            const displayName = app.nickname ? `${app.fullName} (${app.nickname})` : app.fullName;
            let riderTarget = {
                id: `RIDER-${Date.now().toString().slice(-4)}`,
                name: displayName,
                phone: app.phone,
                plate: app.plate || "-",
                zone: app.zone || "รอบตลาดวิศิษฐ์ชัย",
                status: "available",
                baseFee: 40,
                lat: Number(((typeof MARKET_ORIGIN !== 'undefined' && MARKET_ORIGIN.lat) || 15.2285) + (Math.random() - 0.5) * 0.01).toFixed(4),
                lng: Number(((typeof MARKET_ORIGIN !== 'undefined' && MARKET_ORIGIN.lng) || 104.8565) + (Math.random() - 0.5) * 0.01).toFixed(4),
                avatar: "🛵",
                motorcycleModel: app.motorcycleModel || "",
                promptPay: app.promptPayNumber || app.phone || "",
                accessCode: app.accessCode,
                codSettledToday: 0
            };
            riders.unshift(riderTarget);
            saveCommunityRiders(riders);
            loginRiderWithProfile(riderTarget);
            return;
        }
    }

    alert("⚠️ ไม่พบรหัสดังกล่าว..กรุณาตรวจสอบความถูกต้อง หรือถ้าได้รับการอนุมัติแล้วโปรดดูที่กล่องรับข้อความจากเบอร์โทรศัพท์หรือที่ไลน์ที่ให้ไว้กับทางเรา");
    showToast("⚠️ ไม่พบรหัสดังกล่าว..กรุณาตรวจสอบความถูกต้อง หรือถ้าได้รับการอนุมัติแล้วโปรดดูที่กล่องรับข้อความจากเบอร์โทรศัพท์หรือที่ไลน์ที่ให้ไว้กับทางเรา");
}
window.handleRiderPhoneLoginSubmit = handleRiderPhoneLoginSubmit;

function loginRiderWithProfile(r) {
    state.activeRider = {
        isLoggedIn: true,
        riderId: r.id,
        name: r.name,
        phone: r.phone,
        license: r.plate
    };
    saveRiderToStorage(state.activeRider);
    closeRiderLoginModal();
    setActiveRoleView("rider");
    renderAuthHeaderButtons();
    renderRiderScreen();
    updateRiderRoleButtonUI();
    showToast(`🎉 เข้าสู่ระบบไรเดอร์สำเร็จ! ยินดีต้อนรับ ${r.name}`);
}
window.loginRiderWithProfile = loginRiderWithProfile;

function logoutRider() {
    state.activeRider = null;
    saveRiderToStorage(null);
    setActiveRoleView("customer");
    renderAuthHeaderButtons();
    updateRiderRoleButtonUI();
    showToast("🚪 ออกจากระบบไรเดอร์เรียบร้อยแล้ว");
}
window.logoutRider = logoutRider;

function updateRiderRoleButtonUI() {
    const btn = document.getElementById("role-btn-rider");
    if (!btn) return;
    const isRiderLoggedIn = !!(state.activeRider && state.activeRider.isLoggedIn);
    if (isRiderLoggedIn) {
        btn.classList.add("logged-in");
    } else {
        btn.classList.remove("logged-in");
    }
}
window.updateRiderRoleButtonUI = updateRiderRoleButtonUI;

// ── ไรเดอร์กด Step 1: รับของแล้ว ออกเดินทางส่งของสด ──────────────────────────────
function handleRiderStartDelivery() {
    if (!state.activeOrder) {
        assignSampleOrderToRider();
    }

    const timeStr = new Date().toLocaleTimeString("th-TH", { hour: "2-digit", minute: "2-digit" }) + " น.";
    state.activeOrder.status = "delivering";
    state.activeOrder.startedDeliveryAt = timeStr;

    // ซิงค์ชื่อและเบอร์ไรเดอร์
    if (state.activeRider && state.activeRider.isLoggedIn) {
        state.activeOrder.riderName = state.activeRider.name;
        state.activeOrder.riderPhone = state.activeRider.phone;
        state.activeOrder.riderPlate = state.activeRider.license;
    }

    // อัปเดตสถานะไรเดอร์ในทำเนียบกองยานเป็น on_delivery
    try {
        const riders = loadCommunityRiders();
        const curRider = riders.find(r => 
            (state.activeRider && (r.id === state.activeRider.riderId || r.phone === state.activeRider.phone)) ||
            r.name === state.activeOrder.riderName
        );
        if (curRider) {
            curRider.status = "on_delivery";
            saveCommunityRiders(riders);
        }
    } catch(e) {}

    saveActiveOrderToStorage(state.activeOrder);

    // Render ทุกมุมมองที่เกี่ยวข้อง
    renderRiderScreen();
    if (typeof renderTrackingScreen === "function") renderTrackingScreen();
    if (typeof renderHubPickingList === "function") renderHubPickingList();
    if (typeof initAdminRiderRadarMap === "function") initAdminRiderRadarMap();

    showToast("🛵 ไรเดอร์รับของแล้ว ออกเดินทางส่งของสด! ลูกค้าสามารถติดตาม GPS ได้แบบเรียลไทม์");
}
window.handleRiderStartDelivery = handleRiderStartDelivery;

// ── ไรเดอร์กด Step 2: ส่งมอบสำเร็จ (ถึงหน้าบ้านลูกค้า) ──────────────────────────
function handleRiderCompleteDelivery() {
    if (!state.activeOrder) {
        showToast("⚠️ ไม่มีออเดอร์ที่กำลังนำส่ง");
        return;
    }

    const timeStr = new Date().toLocaleTimeString("th-TH", { hour: "2-digit", minute: "2-digit" }) + " น.";
    state.activeOrder.status = "delivered";
    state.activeOrder.deliveredAt = timeStr;

    // คืนสถานะไรเดอร์กลับมาเป็น available
    let riderName = state.activeOrder.riderName || (state.activeRider ? state.activeRider.name : "ไรเดอร์");
    let riderPhone = state.activeOrder.riderPhone || (state.activeRider ? state.activeRider.phone : "-");
    try {
        const riders = loadCommunityRiders();
        const curRider = riders.find(r => 
            (state.activeRider && (r.id === state.activeRider.riderId || r.phone === state.activeRider.phone)) ||
            r.name === riderName
        );
        if (curRider) {
            curRider.status = "available";
            saveCommunityRiders(riders);
        }
    } catch(e) {}

    // บันทึกรายการลงในสรุปผลปฏิบัติงานประจำวัน (Daily Settlements & Reports)
    try {
        const dateKey = getReportDateKey(Date.now());
        const report = aggregateDailyOperations(dateKey);
        let riderRecord = report.riderSettlement.riders.find(r => r.riderName === riderName || r.riderPhone === riderPhone);
        const grandTotal = Number(state.activeOrder.grandTotal || state.activeOrder.total || 0);
        const isCod = (state.activeOrder.paymentType === "cod" || state.activeOrder.paymentType === "cash");
        const refundAmt = Number(state.activeOrder.refundCashTotal || 0);

        if (!riderRecord) {
            riderRecord = {
                riderId: (state.activeRider && state.activeRider.riderId) || `RIDER-${Date.now().toString().slice(-4)}`,
                riderName: riderName,
                riderPhone: riderPhone,
                tripsCount: 1,
                riderFeeEarned: 40,
                codCollected: isCod ? grandTotal : 0,
                refundHanded: refundAmt,
                netCashToHub: isCod ? (grandTotal - 40 - refundAmt) : (-40),
                isSettled: false
            };
            report.riderSettlement.riders.push(riderRecord);
        } else {
            riderRecord.tripsCount = (riderRecord.tripsCount || 0) + 1;
            riderRecord.riderFeeEarned = (riderRecord.riderFeeEarned || 0) + 40;
            if (isCod) riderRecord.codCollected = (riderRecord.codCollected || 0) + grandTotal;
            if (refundAmt > 0) riderRecord.refundHanded = (riderRecord.refundHanded || 0) + refundAmt;
            riderRecord.netCashToHub = riderRecord.codCollected - riderRecord.riderFeeEarned - (riderRecord.refundHanded || 0);
        }
        localStorage.setItem(`talathub_daily_report_${dateKey}`, JSON.stringify(report));
    } catch(e) {
        console.warn("Settlement record error:", e);
    }

    saveActiveOrderToStorage(state.activeOrder);

    renderRiderScreen();
    if (typeof renderTrackingScreen === "function") renderTrackingScreen();
    if (typeof renderHubSettlement === "function") renderHubSettlement();

    openRiderDeliveryCompleteModal();
    showToast("🎉 ส่งมอบของสดถึงมือลูกค้าสำเร็จแล้ว! ได้รับค่ารอบ +฿40");
}
window.handleRiderCompleteDelivery = handleRiderCompleteDelivery;

// ── เปิด Modal สรุปส่งของสำเร็จ ─────────────────────────────────────────────
function openRiderDeliveryCompleteModal() {
    const modal = document.getElementById("rider-delivery-complete-modal");
    if (!modal) return;

    const o = state.activeOrder;
    if (o) {
        const orderIdEl = document.getElementById("rdc-order-id");
        const custNameEl = document.getElementById("rdc-customer-name");
        const custPhoneEl = document.getElementById("rdc-customer-phone");
        const custAddrEl = document.getElementById("rdc-customer-address");
        const payDescEl = document.getElementById("rdc-payment-desc");
        const orderAmtEl = document.getElementById("rdc-order-amount");
        const deliveredTimeEl = document.getElementById("rdc-delivered-time");
        const refundBox = document.getElementById("rdc-refund-box");
        const refundAmtEl = document.getElementById("rdc-refund-amount");

        if (orderIdEl) orderIdEl.textContent = o.orderId || "#TH-9999";
        if (custNameEl) custNameEl.textContent = o.customerName || "ลูกค้าทั่วไป";
        if (custPhoneEl) custPhoneEl.textContent = o.customerPhone || "-";
        if (custAddrEl) custAddrEl.textContent = o.address || "อำเภอบ้านบึง จังหวัดชลบุรี";

        const pType = (o.paymentType || "promptpay").toLowerCase();
        const isCod = pType === "cod" || pType === "cash";
        if (payDescEl) payDescEl.textContent = isCod ? "💵 เงินสดปลายทาง (COD)" : "📱 ชำระผ่านระบบแล้ว";
        if (orderAmtEl) orderAmtEl.textContent = `฿${(o.grandTotal || o.total || 0).toLocaleString()}`;
        if (deliveredTimeEl) deliveredTimeEl.textContent = o.deliveredAt || (new Date().toLocaleTimeString("th-TH", { hour: "2-digit", minute: "2-digit" }) + " น.");

        if (refundBox) {
            if (o.refundCashTotal && o.refundCashTotal > 0) {
                refundBox.classList.remove("hidden");
                if (refundAmtEl) refundAmtEl.textContent = `฿${o.refundCashTotal}`;
            } else {
                refundBox.classList.add("hidden");
            }
        }

        // Setup Photo Proof Preview
        const proofImg = document.getElementById("rider-proof-img");
        const proofBox = document.getElementById("rider-proof-preview-box");
        const proofTag = document.getElementById("rider-proof-status-tag");
        const proofBtn = document.getElementById("rider-proof-btn-text");
        if (o.deliveryProofImage && proofImg && proofBox) {
            proofImg.src = o.deliveryProofImage;
            proofBox.classList.remove("hidden");
            if (proofTag) {
                proofTag.textContent = "✓ แนบรูปแล้ว";
                proofTag.className = "text-[9px] bg-emerald-100 text-emerald-800 font-bold px-2 py-0.5 rounded-full";
            }
            if (proofBtn) proofBtn.textContent = "📷 เปลี่ยนรูปหลักฐานการวางของ";
        } else {
            if (proofBox) proofBox.classList.add("hidden");
            if (proofImg) proofImg.src = "";
            if (proofTag) {
                proofTag.textContent = "ยังไม่แนบรูป";
                proofTag.className = "text-[9px] bg-slate-200 text-slate-600 px-2 py-0.5 rounded-full font-bold";
            }
            if (proofBtn) proofBtn.textContent = "📷 ถ่ายรูป / แนบรูปการวางของสด";
        }
    }

    modal.classList.remove("hidden");
}
window.openRiderDeliveryCompleteModal = openRiderDeliveryCompleteModal;

// Rider Photo Proof Upload Handler
function handleRiderDeliveryProofUpload(event) {
    const file = event.target.files && event.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = function (e) {
        const dataUrl = e.target.result;
        const img = document.getElementById("rider-proof-img");
        const box = document.getElementById("rider-proof-preview-box");
        const tag = document.getElementById("rider-proof-status-tag");
        const btnText = document.getElementById("rider-proof-btn-text");
        if (img) img.src = dataUrl;
        if (box) box.classList.remove("hidden");
        if (tag) {
            tag.textContent = "✓ แนบรูปแล้ว";
            tag.className = "text-[9px] bg-emerald-100 text-emerald-800 font-bold px-2 py-0.5 rounded-full";
        }
        if (btnText) btnText.textContent = "📷 เปลี่ยนรูปหลักฐานการวางของ";
        if (state.activeOrder) {
            state.activeOrder.deliveryProofImage = dataUrl;
            saveActiveOrderToStorage(state.activeOrder);
        }
        showToast("📸 แนบรูปถ่ายหลักฐานการส่งมอบของสดเรียบร้อยแล้ว!");
    };
    reader.readAsDataURL(file);
}
window.handleRiderDeliveryProofUpload = handleRiderDeliveryProofUpload;

