function resetRiderOrderForNextJob() {
    closeRiderDeliveryCompleteModal();
    // สร้างออเดอร์ใหม่พร้อมรับงาน
    assignSampleOrderToRider();
    showToast("🛵 ไรเดอร์สแตนด์บายพร้อมรับงานรอบถัดไปแล้ว!");
}
