// ==========================================
// HERO PROMOTIONAL BANNER CAROUSEL (3 BANNERS)
// ==========================================
let _currentHeroSlide = 0;
let _heroBannerInterval = null;
let _heroTouchStartX = 0;
let _heroTouchEndX = 0;

function goToHeroBannerSlide(index) {
    const track = document.getElementById("hero-carousel-track");
    const dots = document.querySelectorAll(".hero-dot");
    if (!track) return;

    _currentHeroSlide = (index + 3) % 3;
    track.style.transform = `translateX(-${_currentHeroSlide * 100}%)`;

    dots.forEach((dot, idx) => {
        if (idx === _currentHeroSlide) {
            dot.className = "hero-dot active w-5 h-1.5 rounded-full bg-emerald-400 transition-all shadow-xs";
        } else {
            dot.className = "hero-dot w-1.5 h-1.5 rounded-full bg-white/50 hover:bg-white transition-all";
        }
    });
}

function nextHeroBannerSlide(e) {
    if (e && e.stopPropagation) e.stopPropagation();
    goToHeroBannerSlide(_currentHeroSlide + 1);
    restartHeroBannerAutoplay();
}

function prevHeroBannerSlide(e) {
    if (e && e.stopPropagation) e.stopPropagation();
    goToHeroBannerSlide(_currentHeroSlide - 1);
    restartHeroBannerAutoplay();
}

function startHeroBannerAutoplay() {
    stopHeroBannerAutoplay();
    _heroBannerInterval = setInterval(() => {
        goToHeroBannerSlide(_currentHeroSlide + 1);
    }, 4500);
}

function stopHeroBannerAutoplay() {
    if (_heroBannerInterval) {
        clearInterval(_heroBannerInterval);
        _heroBannerInterval = null;
    }
}

function restartHeroBannerAutoplay() {
    startHeroBannerAutoplay();
}

function handleHeroBannerClick(index) {
    if (index === 0) {
        // Slide 1: ตลาดสดพรีเมี่ยม
        const catalogEl = document.getElementById("categories-container") || document.getElementById("catalog-section");
        if (catalogEl) {
            catalogEl.scrollIntoView({ behavior: "smooth" });
        }
        showToast("🛒 เลือกชมของสดคัดเกรดจาก 100 แผงค้าตลาดวิศิษฐ์ชัยได้เลยครับ");
    } else if (index === 1) {
        // Slide 2: เฮียส่ง ส่งตรงถึงมือคุณ รวดเร็ว ทันใจ
        openLocationModal();
        showToast("🛵 ระบุพิกัดจัดส่งเพื่อเช็ครอบส่งด่วน 30 นาทีถึงหน้าบ้าน");
    } else if (index === 2) {
        // Slide 3: คูปองส่วนลดพิเศษ WELCOMESONG ส่งฟรี
        const couponCode = "WELCOMESONG";
        try {
            if (navigator && navigator.clipboard && navigator.clipboard.writeText) {
                navigator.clipboard.writeText(couponCode).catch(() => {});
            }
        } catch (e) {}
        showToast(`🎉 รับสิทธิ์คูปอง '${couponCode}' ส่วนลดค่าส่งเรียบร้อยแล้ว!`);
    }
}

function initHeroBannerCarousel() {
    const container = document.getElementById("hero-banner-carousel-container");
    if (!container) return;

    // Attach touch listeners for mobile swipe
    container.addEventListener("touchstart", (e) => {
        if (e.changedTouches && e.changedTouches[0]) {
            _heroTouchStartX = e.changedTouches[0].screenX;
        }
        stopHeroBannerAutoplay();
    }, { passive: true });

    container.addEventListener("touchend", (e) => {
        if (e.changedTouches && e.changedTouches[0]) {
            _heroTouchEndX = e.changedTouches[0].screenX;
            const diff = _heroTouchStartX - _heroTouchEndX;
            if (Math.abs(diff) > 35) {
                if (diff > 0) nextHeroBannerSlide();
                else prevHeroBannerSlide();
            }
        }
        startHeroBannerAutoplay();
    }, { passive: true });

    container.addEventListener("mouseenter", stopHeroBannerAutoplay);
    container.addEventListener("mouseleave", startHeroBannerAutoplay);

    goToHeroBannerSlide(0);
    startHeroBannerAutoplay();
}

// ==========================================
// 🌟 STALL HERO BANNER CAROUSEL SYSTEM
// ==========================================
const _stallBannerSlides = {};
let _stallBannerAutoplayInterval = null;

function goToStallBannerSlide(stallId, slideIndex, e) {
    if (e && e.stopPropagation) e.stopPropagation();
    const track = document.getElementById(`stall-carousel-track-${stallId}`);
    if (!track) return;

    const totalSlides = track.children ? track.children.length : 2;
    slideIndex = ((slideIndex % totalSlides) + totalSlides) % totalSlides;
    _stallBannerSlides[stallId] = slideIndex;

    track.style.transform = `translateX(-${slideIndex * 100}%)`;

    // Update Indicator Dots dynamically
    const dotsContainer = document.getElementById(`stall-dots-${stallId}`);
    if (dotsContainer) {
        const dots = dotsContainer.querySelectorAll(".stall-banner-dot");
        dots.forEach((dot, idx) => {
            if (idx === slideIndex) {
                dot.className = "stall-banner-dot w-4 h-1.5 rounded-full bg-emerald-400 transition-all shadow-xs cursor-pointer";
            } else {
                dot.className = "stall-banner-dot w-1.5 h-1.5 rounded-full bg-white/60 hover:bg-white transition-all cursor-pointer";
            }
        });
    }
}

function nextStallBannerSlide(stallId, e) {
    if (e && e.stopPropagation) e.stopPropagation();
    const track = document.getElementById(`stall-carousel-track-${stallId}`);
    const totalSlides = track && track.children ? track.children.length : 2;
    const current = _stallBannerSlides[stallId] || 0;
    goToStallBannerSlide(stallId, (current + 1) % totalSlides);
}

function prevStallBannerSlide(stallId, e) {
    if (e && e.stopPropagation) e.stopPropagation();
    const track = document.getElementById(`stall-carousel-track-${stallId}`);
    const totalSlides = track && track.children ? track.children.length : 2;
    const current = _stallBannerSlides[stallId] || 0;
    goToStallBannerSlide(stallId, (current - 1 + totalSlides) % totalSlides);
}

function toggleOwnerBannerSlide(stallId, ownerSlideIndex, e) {
    if (e && e.stopPropagation) e.stopPropagation();
    const current = _stallBannerSlides[stallId] || 0;
    if (current === ownerSlideIndex) {
        goToStallBannerSlide(stallId, 0);
    } else {
        goToStallBannerSlide(stallId, ownerSlideIndex);
    }
}
window.toggleOwnerBannerSlide = toggleOwnerBannerSlide;

function initStallBannerCarousels() {
    // Attach touch gestures to each stall banner container
    document.querySelectorAll("[id^='stall-banner-container-']").forEach(container => {
        const stallId = container.id.replace("stall-banner-container-", "");
        let touchStartX = 0;
        let touchEndX = 0;

        container.addEventListener("touchstart", (e) => {
            if (e.changedTouches && e.changedTouches[0]) {
                touchStartX = e.changedTouches[0].screenX;
            }
        }, { passive: true });

        container.addEventListener("touchend", (e) => {
            if (e.changedTouches && e.changedTouches[0]) {
                touchEndX = e.changedTouches[0].screenX;
                const diff = touchStartX - touchEndX;
                if (Math.abs(diff) > 35) {
                    if (diff > 0) nextStallBannerSlide(stallId);
                    else prevStallBannerSlide(stallId);
                }
            }
        }, { passive: true });
    });

    // Start gentle auto-slide rotation for visible stalls (cycles every 5.5s)
    if (_stallBannerAutoplayInterval) clearInterval(_stallBannerAutoplayInterval);
    _stallBannerAutoplayInterval = setInterval(() => {
        if (state.currentRole !== 'customer' || (state.currentScreen && state.currentScreen !== 'market')) return;
        const containers = document.querySelectorAll("[id^='stall-banner-container-']");
        if (!containers || containers.length === 0) return;
        
        containers.forEach(container => {
            const rect = container.getBoundingClientRect();
            if (rect.top < window.innerHeight && rect.bottom > 0) {
                const stallId = container.id.replace("stall-banner-container-", "");
                nextStallBannerSlide(stallId);
            }
        });
    }, 5500);
}

// Preview modal carousel functions
let _previewSlideIndex = 0;
function goToPreviewBannerSlide(idx) {
    const track = document.getElementById("preview-carousel-track");
    const totalSlides = track && track.children ? track.children.length : 2;
    _previewSlideIndex = ((idx % totalSlides) + totalSlides) % totalSlides;
    if (track) track.style.transform = `translateX(-${_previewSlideIndex * 100}%)`;
    const dotsContainer = document.getElementById("preview-dots-container");
    if (dotsContainer) {
        const dots = dotsContainer.querySelectorAll(".preview-dot");
        dots.forEach((dot, dIdx) => {
            dot.className = dIdx === _previewSlideIndex ? "preview-dot w-4 h-1.5 rounded-full bg-emerald-400 transition-all cursor-pointer" : "preview-dot w-1.5 h-1.5 rounded-full bg-white/60 hover:bg-white transition-all cursor-pointer";
        });
    }
}
function nextPreviewBannerSlide() { goToPreviewBannerSlide(_previewSlideIndex + 1); }
function prevPreviewBannerSlide() { goToPreviewBannerSlide(_previewSlideIndex - 1); }

// Window registrations
window.goToHeroBannerSlide = goToHeroBannerSlide;
window.nextHeroBannerSlide = nextHeroBannerSlide;
window.prevHeroBannerSlide = prevHeroBannerSlide;
window.handleHeroBannerClick = handleHeroBannerClick;
window.initHeroBannerCarousel = initHeroBannerCarousel;
window.triggerManualStallShuffle = triggerManualStallShuffle;
window.toggleStallRotationPause = toggleStallRotationPause;
window.goToStallBannerSlide = goToStallBannerSlide;
window.nextStallBannerSlide = nextStallBannerSlide;
window.prevStallBannerSlide = prevStallBannerSlide;
window.initStallBannerCarousels = initStallBannerCarousels;
window.goToPreviewBannerSlide = goToPreviewBannerSlide;
window.nextPreviewBannerSlide = nextPreviewBannerSlide;
window.prevPreviewBannerSlide = prevPreviewBannerSlide;

// Auto-sanitize test & mock data on application launch
function autoSanitizeProductionData() {
    const mockOrderIds = ["#TH-6114", "#TH-8101", "#TH-8102", "#TH-8103", "#TH-5324", "#TH-9568", "#TH-4692", "TH-6114", "TH-8101", "TH-8102", "TH-8103", "TH-5324", "TH-9568", "TH-4692"];
    
    // 1. Active order
    try {
        const savedOrder = localStorage.getItem("talathub_active_order");
        if (savedOrder) {
            const parsed = JSON.parse(savedOrder);
            if (!parsed || !parsed.orderId || mockOrderIds.includes(parsed.orderId) || (typeof parsed.orderId === "string" && parsed.orderId.startsWith("#TH-810"))) {
                localStorage.removeItem("talathub_active_order");
            }
        }
    } catch (e) {}

    // 2. Order history
    try {
        const rawHist = localStorage.getItem("talathub_order_history");
        if (rawHist) {
            let hist = JSON.parse(rawHist);
            if (Array.isArray(hist)) {
                hist = hist.filter(o => o && o.orderId && !mockOrderIds.includes(o.orderId) && !o.orderId.startsWith("#TH-810"));
                localStorage.setItem("talathub_order_history", JSON.stringify(hist));
            }
        }
    } catch (e) {}

    // 3. Community riders & Rider applications: Complete purge of mock & sample riders
    try {
        const rawApps = localStorage.getItem("talathub_rider_applications");
        let apps = [];
        if (rawApps) {
            apps = JSON.parse(rawApps);
            if (Array.isArray(apps)) {
                apps = apps.filter(a => a && !isMockRiderApplication(a));
                localStorage.setItem("talathub_rider_applications", JSON.stringify(apps));
            }
        }

        const rawRiders = localStorage.getItem("talathub_community_riders");
        if (rawRiders) {
            let riders = JSON.parse(rawRiders);
            if (Array.isArray(riders)) {
                riders = riders.filter(r => r && !isMockCommunityRider(r));
                localStorage.setItem("talathub_community_riders", JSON.stringify(riders));
            }
        }
    } catch (e) {}

    // 4. Logged in rider
    try {
        const savedRider = localStorage.getItem("talathub_logged_in_rider");
        if (savedRider) {
            const r = JSON.parse(savedRider);
            if (r && (r.riderId === "rider_somchai" || r.riderId === "rider_sombat" || (r.name && r.name.includes("สมชาย")) || isMockCommunityRider(r))) {
                localStorage.removeItem("talathub_logged_in_rider");
            }
        }
    } catch (e) {}

    // 5. Force Purge old mock stalls from LocalStorage once
    try {
        if (localStorage.getItem("talathub_mock_purged_final_v1") !== "true") {
            localStorage.removeItem("talathub_custom_market_stalls");
            localStorage.removeItem("talathub_favorite_stalls");
            localStorage.removeItem("talathub_stall_catalog_database");
            localStorage.removeItem("talathub_merchant_applications");
            localStorage.setItem("talathub_mock_purged_final_v1", "true");
        }
    } catch (e) {}

    // 6. Favorites: filter out old mock stalls
    try {
        const savedFavs = localStorage.getItem("talathub_favorite_stalls");
        if (savedFavs) {
            let favs = JSON.parse(savedFavs);
            if (Array.isArray(favs)) {
                favs = favs.filter(id => id && (id.startsWith("stall_new_") || id.startsWith("APP-")));
                localStorage.setItem("talathub_favorite_stalls", JSON.stringify(favs));
            }
        }
    } catch (e) {}

    // 7. Cart: 1-time user-requested clean reset & sanitize
    try {
        if (localStorage.getItem("talathub_cart_reset_v924") !== "done") {
            localStorage.removeItem("talathub_cart");
            localStorage.setItem("talathub_cart", JSON.stringify([]));
            localStorage.setItem("talathub_cart_reset_v924", "done");
        }
    } catch (e) {}
    try {
        const savedCart = localStorage.getItem("talathub_cart");
        if (savedCart) {
            let cart = JSON.parse(savedCart);
            if (Array.isArray(cart)) {
                cart = cart.filter(item => item && (item.productId || item.id || item.name));
                localStorage.setItem("talathub_cart", JSON.stringify(cart));
            }
        }
    } catch (e) {}

    // 8. Custom stalls in localStorage: filter out old mock stalls
    try {
        const rawCustom = localStorage.getItem("talathub_custom_market_stalls");
        if (rawCustom) {
            let stalls = JSON.parse(rawCustom);
            if (Array.isArray(stalls)) {
                stalls = stalls.filter(s => s && s.stallId && (s.stallId.startsWith("stall_new_") || s.stallId.startsWith("APP-")));
                localStorage.setItem("talathub_custom_market_stalls", JSON.stringify(stalls));
            }
        }
    } catch (e) {}

    // 9. Stalls Catalog Database: wipe old mock stalls
    try {
        const rawCat = localStorage.getItem("talathub_stall_catalog_database");
        if (rawCat) {
            let db = JSON.parse(rawCat);
            if (db && typeof db === "object") {
                const cleanDb = {};
                for (const key of Object.keys(db)) {
                    if (key.startsWith("stall_new_") || key.startsWith("APP-")) {
                        cleanDb[key] = db[key];
                    }
                }
                localStorage.setItem("talathub_stall_catalog_database", JSON.stringify(cleanDb));
            }
        }
    } catch (e) {}

    // 10. Remove mock caches
    try {
        localStorage.removeItem("talathub_pending_stalls");
        localStorage.removeItem("talathub_mock_orders");
        localStorage.removeItem("talathub_rating_reviews");
    } catch (e) {}

}

async function fetchOnlineStallsStartup() {
    try {
        const [resApps, resCustom] = await Promise.allSettled([
            fetch("https://hsong-1f342-default-rtdb.asia-southeast1.firebasedatabase.app/merchant_applications.json").then(r => r.ok ? r.json() : null),
            fetch("https://hsong-1f342-default-rtdb.asia-southeast1.firebasedatabase.app/custom_market_stalls.json").then(r => r.ok ? r.json() : null)
        ]);
        const remoteApps = (resApps.status === 'fulfilled' && resApps.value) || null;
        const remoteCustom = (resCustom.status === 'fulfilled' && resCustom.value) || null;

        let appList = [];
        if (Array.isArray(remoteApps)) appList = remoteApps.filter(Boolean);
        else if (remoteApps && typeof remoteApps === 'object') appList = Object.values(remoteApps).filter(Boolean);

        let customList = [];
        if (Array.isArray(remoteCustom)) customList = remoteCustom.filter(Boolean);
        else if (remoteCustom && typeof remoteCustom === 'object') customList = Object.values(remoteCustom).filter(Boolean);

        let hasChanges = false;

        if (appList.length > 0) {
            appList.forEach(app => {
                if (app && app.status === 'approved' && app.stallData) {
                    if (app.stallData.products && Array.isArray(app.stallData.products)) {
                        app.stallData.products.forEach(p => { if (p && p.image) delete p.image; });
                    }
                    const sData = { ...app.stallData, accessCode: app.accessCode || app.stallData.accessCode };
                    const mIdx = MARKET_DATA.findIndex(s => s.stallId === sData.stallId);
                    if (mIdx >= 0) {
                        MARKET_DATA[mIdx] = { ...MARKET_DATA[mIdx], ...sData };
                    } else {
                        MARKET_DATA.unshift(sData);
                    }
                    if (typeof ALL_100_STALLS !== "undefined" && Array.isArray(ALL_100_STALLS)) {
                        const aIdx = ALL_100_STALLS.findIndex(s => s.stallId === sData.stallId);
                        if (aIdx >= 0) {
                            ALL_100_STALLS[aIdx] = { ...ALL_100_STALLS[aIdx], ...sData };
                        } else {
                            ALL_100_STALLS.unshift(sData);
                        }
                    }
                    hasChanges = true;
                }
            });
            try { localStorage.setItem("talathub_merchant_applications", JSON.stringify(appList)); } catch(e) {}
        }

        if (customList.length > 0) {
            customList.forEach(stall => {
                if (stall && stall.stallId) {
                    if (stall.products && Array.isArray(stall.products)) {
                        stall.products.forEach(p => { if (p && p.image) delete p.image; });
                    }
                    const mIdx = MARKET_DATA.findIndex(s => s.stallId === stall.stallId);
                    if (mIdx >= 0) {
                        MARKET_DATA[mIdx] = { ...MARKET_DATA[mIdx], ...stall };
                    } else {
                        MARKET_DATA.unshift(stall);
                    }
                    if (typeof ALL_100_STALLS !== "undefined" && Array.isArray(ALL_100_STALLS)) {
                        const aIdx = ALL_100_STALLS.findIndex(s => s.stallId === stall.stallId);
                        if (aIdx >= 0) {
                            ALL_100_STALLS[aIdx] = { ...ALL_100_STALLS[aIdx], ...stall };
                        } else {
                            ALL_100_STALLS.unshift(stall);
                        }
                    }
                    hasChanges = true;
                }
            });
            try { localStorage.setItem("talathub_custom_market_stalls", JSON.stringify(customList)); } catch(e) {}
        }

        if (hasChanges) {
            if (typeof renderCatalog === "function") renderCatalog();
            if (typeof renderDirectoryList === "function") renderDirectoryList();
            if (typeof renderFavoriteStallsBar === "function") renderFavoriteStallsBar();
            if (typeof updateStallRotationUI === "function") updateStallRotationUI();
            if (state.currentRole === "merchant" && typeof renderMerchantView === "function") {
                renderMerchantView();
            }
        }
    } catch (e) {
        console.warn("fetchOnlineStallsStartup error:", e);
    }
}
window.fetchOnlineStallsStartup = fetchOnlineStallsStartup;

