function loadMerchantApplications() {
    try {
        const raw = localStorage.getItem("talathub_merchant_applications");
        if (raw !== null) {
            const parsed = JSON.parse(raw);
            if (Array.isArray(parsed)) return parsed;
        }
    } catch (e) {
        console.error("Error loading merchant applications:", e);
    }
    const seedApps = [];
    try {
        localStorage.setItem("talathub_merchant_applications", JSON.stringify(seedApps));
    } catch (e) {}
    return seedApps;
}
window.loadMerchantApplications = loadMerchantApplications;

function saveMerchantApplications(apps) {
    try {
        try {
            localStorage.setItem("talathub_merchant_applications", JSON.stringify(apps));
        } catch (storageErr) {
            console.warn("localStorage quota exceeded for merchant_applications:", storageErr);
        }
        if (isFirebaseReady() && db) {
            db.ref("merchant_applications").set(apps).catch(err => {
                console.warn("Firebase save merchant_applications failed:", err);
            });
        }
        try {
            fetch("https://hsong-1f342-default-rtdb.asia-southeast1.firebasedatabase.app/merchant_applications.json", {
                method: "PUT",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(apps)
            }).catch(() => {});
        } catch (e) {}
    } catch (e) {}
}
window.saveMerchantApplications = saveMerchantApplications;

async function saveMerchantApplicationsAsync(apps) {
    try {
        try {
            localStorage.setItem("talathub_merchant_applications", JSON.stringify(apps));
        } catch (storageErr) {
            console.warn("localStorage quota exceeded for merchant_applications:", storageErr);
        }
        const promises = [];
        if (isFirebaseReady() && db) {
            promises.push(
                db.ref("merchant_applications").set(apps).catch(err => {
                    console.warn("Firebase save merchant_applications failed:", err);
                })
            );
        }
        try {
            promises.push(
                fetch("https://hsong-1f342-default-rtdb.asia-southeast1.firebasedatabase.app/merchant_applications.json", {
                    method: "PUT",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify(apps)
                }).catch(e => console.warn("REST PUT merchant_applications failed:", e))
            );
        } catch(e) {}
        await Promise.allSettled(promises);
    } catch (e) {
        console.warn("saveMerchantApplicationsAsync error:", e);
    }
}
window.saveMerchantApplicationsAsync = saveMerchantApplicationsAsync;

